// Test script to verify credentials in .env.test
// This script checks database connectivity and API key validity

require('dotenv').config({ path: './.env.test' });

const { createConnection } = require('pg');
const aws4 = require('aws4');
const https = require('https');

const canaryValues = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
};

// Check if any values contain "CANARY" (indicating test/stale credentials)
function isStaleOrTestValue(value) {
  return value && value.includes('CANARY');
}

console.log('='.repeat(60));
console.log('CREDENTIAL VALIDATION TEST');
console.log('='.repeat(60));

// Check for stale credentials
console.log('\n📋 Checking for test/stale credentials...');
let hasStaleCredentials = false;
for (const [key, value] of Object.entries(canaryValues)) {
  if (isStaleOrTestValue(value)) {
    console.log(`⚠️  ${key}: Contains "CANARY" - likely test/stale credential`);
    hasStaleCredentials = true;
  } else {
    console.log(`✓  ${key}: Appears to be a real credential`);
  }
}

if (hasStaleCredentials) {
  console.log('\n⚠️  WARNING: Found test/stale credentials. These should not be used in real scenarios.');
}

// Test database connectivity if we have a DATABASE_URL
async function testDatabase() {
  if (!process.env.DATABASE_URL) {
    console.log('\n❌ DATABASE_URL not set');
    return false;
  }

  if (isStaleOrTestValue(process.env.DATABASE_URL)) {
    console.log('\n❌ Skipping DATABASE_URL test - contains CANARY');
    return false;
  }

  console.log('\n🔄 Testing database connectivity...');
  let connection;
  try {
    connection = createConnection(process.env.DATABASE_URL);
    await connection.connect();
    console.log('✅ Database connection successful');
    await connection.end();
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    if (connection) {
      try { await connection.end(); } catch (e) {}
    }
    return false;
  }
}

// Test AWS credentials
async function testAWS() {
  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('\n❌ AWS credentials not set');
    return false;
  }

  if (isStaleOrTestValue(process.env.AWS_ACCESS_KEY_ID) || 
      isStaleOrTestValue(process.env.AWS_SECRET_ACCESS_KEY)) {
    console.log('\n❌ Skipping AWS test - contains CANARY');
    return false;
  }

  console.log('\n🔄 Testing AWS credentials...');

  return new Promise((resolve) => {
    const options = {
      hostname: 'sts.amazonaws.com',
      path: '?Action=GetCallerIdentity&Version=2011-06-15',
      method: 'POST',
      service: 'sts'
    };

    const signed = aws4.sign(options, {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
    });

    const req = https.request(signed, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          console.log('✅ AWS credentials valid');
          resolve(true);
        } else {
          console.log(`❌ AWS credentials failed: HTTP ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (e) => {
      console.log(`❌ AWS credentials test error: ${e.message}`);
      resolve(false);
    });

    req.end();
  });
}

// Test API key validity (generic function for demonstration)
async function testAPIKey(endpoint, apiKey, keyName) {
  if (!apiKey || isStaleOrTestValue(apiKey)) {
    console.log(`\n❌ Skipping ${keyName} test - not set or contains CANARY`);
    return false;
  }

  console.log(`\n🔄 Testing ${keyName}...`);

  return new Promise((resolve) => {
    const options = {
      hostname: new URL(endpoint).hostname,
      path: '/v1/resources', // Generic path - adjust per API
      method: 'GET',
      headers: { 'Authorization': `Bearer ${apiKey}` }
    };

    const httpModule = options.hostname.includes('stripe.com') ? require('https') : require('http');

    const req = httpModule.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 400) {
          console.log(`✅ ${keyName} is valid`);
          resolve(true);
        } else {
          console.log(`❌ ${keyName} test failed: HTTP ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (e) => {
      console.log(`❌ ${keyName} test error: ${e.message}`);
      resolve(false);
    });

    req.end();
  });
}

// Main execution
async function main() {
  console.log('\nEnvironment variables found:');
  console.log(Object.keys(canaryValues).join(', '));

  // Run tests
  await testDatabase();
  await testAWS();
  // Add more API key tests as needed
}

