  console.log('SUGGESTED ACTION: Replace these with valid credentials or remove them.');
}

// Check specific credential patterns
console.log('\n🔍 Credential Pattern Analysis:');

// Check DATABASE_URL
if (canaryValues.DATABASE_URL) {
  const dbUrl = canaryValues.DATABASE_URL;
  console.log('\n📦 DATABASE_URL:');
  try {
    const parsed = new URL(dbUrl);
    console.log(`   Protocol: ${parsed.protocol}`);
    console.log(`   Host: ${parsed.hostname}`);
    console.log(`   Port: ${parsed.port}`);
    console.log(`   Path: ${parsed.pathname}`);
    console.log(`   Username: ${parsed.username || 'none'}`);
    console.log(`   Contains password: ${!!parsed.password}`);

    if (isStaleOrTestValue(dbUrl)) {
      console.log('   ❌ Contains test markers (CANARY)');
    } else {
      console.log('   ℹ️  Would attempt connection to database');
    }
  } catch (e) {
    console.log(`   ❌ Invalid URL format: ${e.message}`);
  }
}

// Check AWS credentials
if (canaryValues.AWS_ACCESS_KEY_ID && canaryValues.AWS_SECRET_ACCESS_KEY) {
  console.log('\n☁️  AWS Credentials:');
  const keyId = canaryValues.AWS_ACCESS_KEY_ID;
  const secret = canaryValues.AWS_SECRET_ACCESS_KEY;

  console.log(`   Key ID: ${keyId.substring(0, 4)}...${keyId.substring(keyId.length - 4)}`);
  console.log(`   Secret: ${secret.substring(0, 4)}...${secret.length > 20 ? '...' + secret.substring(secret.length - 4) : ''}`);

  if (isStaleOrTestValue(keyId) || isStaleOrTestValue(secret)) {
    console.log('   ❌ Contains test markers (CANARY)');
  } else {
