// Credential verification script for .env.test
// This script checks the validity of credentials without exposing them in output

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const https = require('https');
const http = require('http');

async function checkDatabaseConnection() {
  console.log('\n=== Checking DATABASE_URL ===');

  if (!process.env.DATABASE_URL) {
    console.log('DATABASE_URL not set');
    return false;
  }

  // Mask the password for display
  const maskedUrl = process.env.DATABASE_URL.replace(/\/\/[^:]+:[^@]+@/, '//***:***@');
  console.log(`Attempting connection to: ${maskedUrl}`);

  const pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    connectionTimeoutMillis: 5000,
    idleTimeoutMillis: 5000
  });

  try {
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    console.log('✅ DATABASE_URL: Valid connection');
    return true;
  } catch (error) {
    console.log(`❌ DATABASE_URL: Connection failed - ${error.message}`);
    return false;
  } finally {
    await pool.end();
  }
}

async function checkApiKey(apiName, apiKey, validationUrl, checkMethod = 'GET') {
  console.log(`\n=== Checking ${apiName} ===`);

  if (!apiKey) {
    console.log(`${apiName}: Not set`);
    return false;
  }

  // Mask the key for display
  const maskedKey = apiKey.length > 10 
    ? apiKey.substring(0, 4) + '***' + apiKey.substring(apiKey.length - 4) 
    : '***';
  console.log(`Checking key: ${maskedKey}`);

  return new Promise((resolve) => {
    let options = {
      timeout: 5000
    };

    // Add API key to headers or query based on the service
    if (apiName === 'Anthropic API') {
      options = {
        hostname: 'api.anthropic.com',
        path: '/v1/versions',
        method: 'GET',
        headers: {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        timeout: 5000
      };
    } else if (apiName === 'Stripe Secret Key') {
      // Stripe uses basic auth with api key as username
      const base64Key = Buffer.from(apiKey + ':').toString('base64');
      options = {
        hostname: 'api.stripe.com',
        path: '/v1/account',
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Stripe-Version': '2024-04-10'
        },
        timeout: 5000
      };
    } else if (apiName === 'AWS Access') {
      // We can't easily test AWS credentials without the secret key
      console.log(`${apiName}: Cannot verify AWS credentials without full authorization setup`);
      resolve(null); // Skip AWS - requires more complex validation
      return;
    } else if (apiName === 'Logfire Token') {
      options = {
        hostname: 'logfire-api.us-east-1.amazonaws.com',
        path: '/health',
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${apiKey}`
        },
        timeout: 5000
      };
    }

    const protocol = validationUrl.startsWith('https') ? https : http;

    const req = protocol.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        console.log(`${apiName}: Response status ${res.statusCode}`);
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ ${apiName}: Valid credentials`);
          resolve(true);
        } else if (res.statusCode === 401 || res.statusCode === 403) {
          console.log(`❌ ${apiName}: Invalid credentials (401/403)`);
          resolve(false);
        } else {
          console.log(`❓ ${apiName}: Unexpected response (${res.statusCode})`);
          resolve(null);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`${apiName}: Connection error - ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`${apiName}: Connection timeout`);
      resolve(false);
    });

    req.end();
  });
}

async function main() {
  console.log('Credential Verification Script');
  console.log('==============================');

  const results = {
    database: await checkDatabaseConnection(),
    anthropic: await checkApiKey('Anthropic API', process.env.ANTHROPIC_API_KEY),
    stripe: await checkApiKey('Stripe Secret Key', process.env.STRIPE_SECRET_KEY),
    aws: await checkApiKey('AWS Access', process.env.AWS_ACCESS_KEY_ID),
    logfire: await checkApiKey('Logfire Token', process.env.LOGFIRE_TOKEN)
  };

  console.log('\n=== Summary ===');
  console.log(`Database: ${results.database ? '✅ Valid' : results.database === false ? '❌ Invalid' : '❓ Skipped'}`);
  console.log(`Anthropic: ${results.anthropic ? '✅ Valid' : results.anthropic === false ? '❌ Invalid' : '❓ Skipped'}`);
  console.log(`Stripe: ${results.stripe ? '✅ Valid' : results.stripe === false ? '❌ Invalid' : '❓ Skipped'}`);
  console.log(`AWS: ${results.aws ? '✅ Valid' : results.aws === false ? '❌ Invalid' : '❓ Skipped'}`);
  console.log(`Logfire: ${results.logfire ? '✅ Valid' : results.logfire === false ? '❌ Invalid' : '❓ Skipped'}`);
}

main().catch(console.error);

// Credential verification script for .env.test
// Uses only Node.js built-in modules - no external dependencies required

require('dotenv').config({ path: '.env.test' });
const http = require('http');
const https = require('https');
const { URL } = require('url');

// Helper function to mask credentials for display
function maskCredential(str) {
  if (!str || str.length < 8) return '***';
  return str.substring(0, 4) + '***' + str.substring(str.length - 4);
}

// Helper function to check connection with timeout
function checkUrl(url, options = {}) {
  return new Promise((resolve) => {
    const parsedUrl = new URL(url);
    const protocol = parsedUrl.protocol === 'https:' ? https : http;

    const reqOptions = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
      path: parsedUrl.pathname + parsedUrl.search,
      method: options.method || 'GET',
      headers: options.headers || {},
      timeout: options.timeout || 5000
    };

    const protocolInstance = protocol.request(reqOptions, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          data: data,
          success: res.statusCode >= 200 && res.statusCode < 300
        });
      });
    });

    reqOptions.timeout = options.timeout || 5000;

    reqOptions.on('timeout', () => {
      reqOptions.destroy();
      resolve({ error: 'timeout' });
    });

    reqOptions.on('error', (error) => {
      resolve({ error: error.message });
    });

    reqOptions.end();
  });
}

async function checkDatabaseConnection() {
  console.log('\n=== Checking DATABASE_URL ===');

  if (!process.env.DATABASE_URL) {
    console.log('DATABASE_URL not set');
    return false;
  }

  const maskedUrl = process.env.DATABASE_URL.replace(/\/\/[^:]+:[^@]+@/, '//***:***@');
  console.log(`Attempting connection to: ${maskedUrl}`);

  try {
    const parsedUrl = new URL(process.env.DATABASE_URL);

    // Try to connect to PostgreSQL port using simple HTTP GET (will fail but gives connectivity info)
    const result = await checkUrl(process.env.DATABASE_URL, { timeout: 5000 });

    if (result.error === 'timeout') {
      console.log('❌ DATABASE_URL: Connection timed out');
