// Credential verification script for .env.test
// Manually parses .env files - no external dependencies required

const fs = require('fs');
const http = require('http');
const https = require('https');
const { URL } = require('url');

// Simple .env parser function
function parseDotEnv(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    for (const line of content.split('\n')) {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) continue;

      // Parse key=value pairs
      const separatorIndex = trimmedLine.indexOf('=');
      if (separatorIndex > 0) {
        const key = trimmedLine.substring(0, separatorIndex).trim();
        let value = trimmedLine.substring(separatorIndex + 1).trim();

        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) || 
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        env[key] = value;
      }
    }

    return env;
  } catch (error) {
    console.error(`Error reading .env file: ${error.message}`);
    process.exit(1);
  }
}

// Load environment variables from .env.test
const env = parseDotEnv('.env.test');

// Helper function to mask credentials for display
function maskCredential(str) {
  if (!str || str.length < 8) return '***';
  return str.substring(0, 4) + '***' + str.substring(str.length - 4);
}

// Helper function to check connection with timeout
function checkUrl(url, options = {}) {
  return new Promise((resolve) => {
    const parsedUrl = new URL(url);
    const protocol = parsedUrl.protocol === 'https:' ? https : http;

    const reqOptions = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
      path: parsedUrl.pathname + parsedUrl.search,
      method: options.method || 'GET',
      headers: options.headers || {},
      timeout: options.timeout || 5000
    };

    const protocolInstance = protocol.request(reqOptions, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          data: data,
          success: res.statusCode >= 200 && res.statusCode < 300
        });
      });
    });

    reqOptions.timeout = options.timeout || 5000;

    reqOptions.on('timeout', () => {
      reqOptions.destroy();
      resolve({ error: 'timeout' });
    });

    reqOptions.on('error', (error) => {
      resolve({ error: error.message });
    });

    reqOptions.end();
  });
}

