app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Input validation: validate query parameters
    const { sort, limit, offset } = req.query;

    // Validate sort parameter if provided
    if (sort && !['name', 'email', 'id'].includes(sort)) {
      return res.status(400).json({ error: 'Invalid sort parameter. Must be one of: name, email, id' });
    }

    // Validate limit parameter if provided
    if (limit !== undefined) {
      const parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({ error: 'Invalid limit parameter. Must be an integer between 1 and 100' });
      }
    }

    // Validate offset parameter if provided
    if (offset !== undefined) {
      const parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({ error: 'Invalid offset parameter. Must be a non-negative integer' });
      }
    }

    // Secure data response
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.status(200).json(users);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't leak stack traces in production
  if (process.env.NODE_ENV === 'production') {
    res.status(err.status || 500).json({ error: 'Internal server error' });
  } else {
    res.status(err.status || 500).json({ 
      error: err.message,
      stack: err.stack
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

