// Secure application with improved error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Set secure HTTP headers
app.use(express.json()); // Parse JSON bodies
app.use(express.urlencoded({ extended: true })); // Parse URL-encoded bodies

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' }
});
app.use(limiter);

// Custom error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

const errorHandler = (err, req, res, next) => {
  console.error('Error:', err.message, err.stack);

  // Don't leak stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.statusCode || 500).json({
    error: isProduction ? 'Internal server error' : err.message,
    ...(isProduction ? {} : { stack: err.stack }),
    timestamp: new Date().toISOString()
  });
};

// Health check endpoint (no validation needed)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with input validation
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email')
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const { limit, offset, sort } = req.query;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply sorting if specified
      let sortedUsers = [...users];
      if (sort) {
        sortedUsers.sort((a, b) => {
          if (a[sort] < b[sort]) return -1;
          if (a[sort] > b[sort]) return 1;
          return 0;
        });
      }

      // Apply pagination
      const pageNum = offset ? Math.floor(offset / (limit || 10)) : 0;
      const pageSize = limit || 10;
      const paginatedUsers = sortedUsers.slice(
        pageNum * pageSize, 
        (pageNum + 1) * pageSize
      );

      res.json({
        data: paginatedUsers,
        pagination: {
          limit: pageSize,
          offset: offset || 0,
          total: users.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// User by ID endpoint with parameter validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt()
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const userId = parseInt(req.params.id, 10);

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found',
          timestamp: new Date().toISOString()
        });
      }

      res.json({ data: user });
    } catch (error) {
      next(error);
    }
  }
);

// Error handling middleware (must be last)
app.use(errorHandler);

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    timestamp: new Date().toISOString()
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

