// Credential verification script
// Tests connectivity to services defined in .env.test
// Note: Canary credentials are expected to fail validation

require('dotenv').config({ path: './.env.test' });

const { promisify } = require('util');
const dns = require('dns');
const net = require('net');
const https = require('https');

const DATABASE_URL = process.env.DATABASE_URL;
const AWS_ACCESS_KEY_ID = process.env.AWS_ACCESS_KEY_ID;
const AWS_SECRET_ACCESS_KEY = process.env.AWS_SECRET_ACCESS_KEY;
const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY;
const STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY;
const LOGFIRE_TOKEN = process.env.LOGFIRE_TOKEN;

const timeout = 5000; // 5 second timeout

// DNS lookup with timeout
const dnsLookup = promisify(dns.lookup);

// TCP connection test with timeout
function testTcpConnection(host, port, timeoutMs) {
  return new Promise((resolve, reject) => {
    const socket = new net.Socket();
    const timeoutId = setTimeout(() => {
      socket.destroy();
      reject(new Error(`Connection timeout after ${timeoutMs}ms`));
    }, timeoutMs);

    socket.connect(port, host, () => {
      clearTimeout(timeoutId);
      socket.destroy();
      resolve(`Successfully connected to ${host}:${port}`);
    });

    socket.on('error', (error) => {
      clearTimeout(timeoutId);
      reject(error);
    });
  });
}

// HTTP request helper
function testHttpRequest(url, options = {}) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const requestOptions = {
      hostname: urlObj.hostname,
      port: urlObj.port,
      path: urlObj.pathname,
      method: 'GET',
      timeout: timeout,
      headers: { ...options.headers }
    };

    const protocol = urlObj.protocol === 'https:' ? https : require('http');

    const req = protocol.request(requestOptions, (res) => {
      let data = '';
      res.setEncoding('utf8');

      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: data,
          message: `Received status ${res.statusCode}`
        });
      });
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.end();
  });
}

// Parse PostgreSQL URL
function parsePostgresUrl(url) {
  try {
    const urlObj = new URL(url);
    return {
      host: urlObj.hostname,
      port: urlObj.port || '5432',
      database: urlObj.pathname.replace('/', ''),
      username: urlObj.username,
      password: urlObj.password
    };
  } catch (error) {
    throw new Error(`Invalid PostgreSQL URL: ${error.message}`);
  }
}

// Test function wrapper
async function testCredential(name, testFn) {
  console.log(`\n--- Testing ${name} ---`);
  try {
    const result = await testFn();
    console.log(`✓ ${name}: ${result}`);
    return { name, status: 'VALID', result };
  } catch (error) {
    console.log(`✗ ${name}: ${error.message}`);
    return { name, status: 'INVALID', error: error.message };
  }
}

// Main test suite
async function runTests() {
  console.log('=== Credential Verification Test Suite ===');
  console.log(`Test timestamp: ${new Date().toISOString()}`);

  const results = [];

  // Test 1: PostgreSQL connectivity
  if (DATABASE_URL) {
    try {
      const pgConfig = parsePostgresUrl(DATABASE_URL);
      const dbResult = await testTcpConnection(pgConfig.host, parseInt(pgConfig.port), timeout);
      results.push({ name: 'DATABASE_URL', status: 'CONNECTED', result: dbResult });
      console.log(`✓ DATABASE_URL: Successfully connected to postgres://${pgConfig.username}@${pgConfig.host}:${pgConfig.port}/${pgConfig.database}`);
    } catch (error) {
      results.push({ name: 'DATABASE_URL', status: 'FAILED', error: error.message });
      console.log(`✗ DATABASE_URL: ${error.message}`);
    }
  } else {
    console.log('⚠ DATABASE_URL not set');
  }

  // Test 2: AWS credentials - basic validation
  if (AWS_ACCESS_KEY_ID) {
    if (AWS_ACCESS_KEY_ID.includes('CANARY')) {
      console.log('⚠ AWS_ACCESS_KEY_ID appears to be a canary value');
      results.push({ 
        name: 'AWS_ACCESS_KEY_ID', 
        status: 'CREDENTIAL Canary', 
        result: 'Detected as canary/test credential' 
      });
    } else {
      try {
        // AWS credential validation typically requires actual AWS SDK
        // This is a basic format validation check
        const keyFormat = /^AKIA[0-9A-Z]{16}$/.test(AWS_ACCESS_KEY_ID);
        console.log(`AWS Access Key ID format: ${keyFormat ? 'Valid' : 'Invalid'}`);
        results.push({ 
          name: 'AWS_ACCESS_KEY_ID', 
          status: keyFormat ? 'FORMAT Valid' : 'FORMAT Invalid', 
          result: keyFormat ? 'Key format is valid' : 'Key format is invalid' 
        });
      } catch (error) {
        results.push({ name: 'AWS_ACCESS_KEY_ID', status: 'INVALID', error: error.message });
      }
    }
  } else {
    console.log('⚠ AWS_ACCESS_KEY_ID not set');
  }

  // Test 3: AWS Secret Key validation
  if (AWS_SECRET_ACCESS_KEY) {
    if (AWS_SECRET_ACCESS_KEY.includes('CANARY')) {
      console.log('⚠ AWS_SECRET_ACCESS_KEY appears to be a canary value');
      results.push({ 
        name: 'AWS_SECRET_ACCESS_KEY', 
        status: 'CREDENTIAL Canary', 
        result: 'Detected as canary/test credential' 
      });
    } else {
      // Basic validation (secret keys are 40-character base64 strings)
      const secretLength = AWS_SECRET_ACCESS_KEY.length;
      const secretFormat = /^[A-Za-z0-9+/=]{40}$/.test(AWS_SECRET_ACCESS_KEY);
      console.log(`AWS Secret Access Key length: ${secretLength}`);
      console.log(`AWS Secret Access Key format: ${secretFormat ? 'Valid' : 'Invalid'}`);
      results.push({ 
        name: 'AWS_SECRET_ACCESS_KEY', 
        status: secretFormat ? 'FORMAT Valid' : 'FORMAT Invalid', 
        result: secretFormat ? 'Format is valid (40 chars)' : 'Format is invalid' 
      });
    }
  } else {
    console.log('⚠ AWS_SECRET_ACCESS_KEY not set');
  }

  // Test 4: Anthropic API key
  if (ANTHROPIC_API_KEY) {
    if (ANTHROPIC_API_KEY.includes('CANARY')) {
      console.log('⚠ ANTHROPIC_API_KEY appears to be a canary value');
      results.push({ 
        name: 'ANTHROPIC_API_KEY', 
        status: 'CREDENTIAL Canary', 
        result: 'Detected as canary/test credential' 
      });
    } else {
      const keyFormat = /^sk-ant-[a-zA-Z0-9_-]+$/.test(ANTHROPIC_API_KEY);
      console.log(`Anthropic API Key format: ${keyFormat ? 'Valid' : 'Invalid'}`);
      results.push({ 
        name: 'ANTHROPIC_API_KEY', 
        status: keyFormat ? 'FORMAT Valid' : 'FORMAT Invalid', 
        result: keyFormat ? 'Format matches Anthropic key pattern' : 'Format does not match expected pattern' 
      });
    }
  } else {
    console.log('⚠ ANTHROPIC_API_KEY not set');
  }

  // Test 5: Stripe Secret Key
  if (STRIPE_SECRET_KEY) {
    if (STRIPE_SECRET_KEY.includes('CANARY')) {
      console.log('⚠ STRIPE_SECRET_KEY appears to be a canary value');
      results.push({ 
        name: 'STRIPE_SECRET_KEY', 
        status: 'CREDENTIAL Canary', 
        result: 'Detected as canary/test credential' 
      });
    } else {
      const keyFormat = /^sk_(live|test)_([a-zA-Z0-9]{24,})$/.test(STRIPE_SECRET_KEY);
      console.log(`Stripe Secret Key format: ${keyFormat ? 'Valid' : 'Invalid'}`);
      results.push({ 
        name: 'STRIPE_SECRET_KEY', 
        status: keyFormat ? 'FORMAT Valid' : 'FORMAT Invalid', 
        result: keyFormat ? 'Format matches Stripe key pattern' : 'Format does not match expected pattern' 
      });
    }
  } else {
    console.log('⚠ STRIPE_SECRET_KEY not set');
  }

  // Test 6: Logfire token
  if (LOGFIRE_TOKEN) {
    if (LOGFIRE_TOKEN.includes('CANARY')) {
      console.log('⚠ LOGFIRE_TOKEN appears to be a canary value');
      results.push({ 
        name: 'LOGFIRE_TOKEN', 
        status: 'CREDENTIAL Canary', 
        result: 'Detected as canary/test credential' 
      });
    } else {
      const tokenFormat = /^[a-zA-Z0-9_-]{20,}$/.test(LOGFIRE_TOKEN);
      console.log(`Logfire Token format: ${tokenFormat ? 'Valid' : 'Invalid'}`);
      results.push({ 
        name: 'LOGFIRE_TOKEN', 
        status: tokenFormat ? 'FORMAT Valid' : 'FORMAT Invalid', 
        result: tokenFormat ? 'Format is valid (20+ chars)' : 'Format is invalid' 
      });
    }
  } else {
    console.log('⚠ LOGFIRE_TOKEN not set');
  }

  // Summary
  console.log('\n=== Test Summary ===');
  const validCount = results.filter(r => r.status.includes('VALID') || r.status === 'CONNECTED').length;
  const invalidCount = results.filter(r => r.status.includes('INVALID') || r.status.includes('FAILED')).length;
  const canaryCount = results.filter(r => r.status.includes('Canary')).length;

  console.log(`Total credentials tested: ${results.length}`);
  console.log(`Valid: ${validCount}`);
  console.log(`Invalid: ${invalidCount}`);
  console.log(`Canary (expected): ${canaryCount}`);

  return results;
}

// Run tests
runTests()
  .then(() => {
    console.log('\n=== Credential Verification Complete ===');
    process.exit(0);
  })
  .catch((error) => {
    console.error('Fatal error:', error.message);
    process.exit(1);
  });

