// Credential verification script
// This script tests the validity of credentials stored in environment variables
// It checks database connectivity and validates API keys

require('dotenv').config({ path: '.env.test' });

const pg = require('pg');
const axios = require('axios');
const AWS = require('aws-sdk');

console.log('=== Credential Verification Script ===\n');

// Helper function to check environment variables
function checkEnvVar(name) {
  const value = process.env[name];
  if (!value) {
    console.log(`❌ ${name}: Not set`);
    return false;
  }

  // Mask the value for security (show first 10 chars, then ...)
  const masked = value.length > 10 
    ? value.substring(0, 10) + '...' 
    : '***';
  console.log(`📋 ${name}: ${masked} (${value.length} chars)`);
  return true;
}

console.log('1. Checking Environment Variables...');
console.log('---');

checkEnvVar('DATABASE_URL');
checkEnvVar('AWS_ACCESS_KEY_ID');
checkEnvVar('AWS_SECRET_ACCESS_KEY');
checkEnvVar('ANTHROPIC_API_KEY');
checkEnvVar('STRIPE_SECRET_KEY');
checkEnvVar('LOGFIRE_TOKEN');

console.log('\n2. Testing Database Connectivity...');
console.log('---');

async function testDatabase() {
  try {
    const databaseUrl = process.env.DATABASE_URL;
    if (!databaseUrl) {
      console.log('⚠️  No DATABASE_URL configured');
      return;
    }

    console.log(`Testing connection to: ${databaseUrl.split('@')[1] || 'host'}`);

    // Create a new client with connection timeout
    const client = new pg.Client({
      connectionString: databaseUrl,
      connectionTimeoutMillis: 5000, // 5 second timeout
      statement_timeout: 3000 // 3 second statement timeout
    });

    await client.connect();
    console.log('✅ Database connection successful');

    // Test a simple query
    const result = await client.query('SELECT 1 as test');
    console.log(`   Query result: ${result.rows[0].test}`);

    await client.end();
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);

    // Provide helpful hints based on error type
    if (error.code === 'ECONNREFUSED') {
      console.log('   Hint: Database server may be unreachable or not running');
    } else if (error.code === 'ETIMEDOUT') {
      console.log('   Hint: Connection timed out - check network/firewall settings');
    } else if (error.code === '28P01') {
      console.log('   Hint: Password authentication failed - check credentials');
    } else if (error.code === '42501') {
      console.log('   Hint: Connection limit exceeded');
    }
  }
}

console.log('3. Testing API Key Validity...');
console.log('---');

async function testAnthropicApiKey() {
  try {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      console.log('⚠️  No ANTHROPIC_API_KEY configured');
      return;
    }

    console.log('Testing Anthropic API key...');

    const response = await axios.post(
      'https://api.anthropic.com/v1/complete',
      {
        prompt: '\n\nHuman: Test\n\nAssistant:',
        model: 'claude-v1',
        max_tokens_to_sample: 1,
        stream: false
      },
      {
        headers: {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        timeout: 10000 // 10 second timeout
      }
    );

    console.log('✅ Anthropic API key is valid');
  } catch (error) {
    if (error.response) {
      console.log(`❌ Anthropic API error: ${error.response.status} - ${error.response.data}`);
    } else if (error.code === 'ECONNREFUSED') {
      console.log('⚠️  Could not connect to Anthropic API (network issue)');
    } else if (error.code === 'ETIMEDOUT') {
      console.log('⚠️  Anthropic API request timed out');
    } else {
      console.log(`❌ Anthropic API validation failed: ${error.message}`);
    }
  }
}

async function testStripeApiKey() {
  try {
    const apiKey = process.env.STRIPE_SECRET_KEY;
    if (!apiKey) {
      console.log('⚠️  No STRIPE_SECRET_KEY configured');
      return;
    }

    console.log('Testing Stripe API key...');

    const response = await axios.get('https://api.stripe.com/v1/account', {
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Stripe-Version': '2023-10-16'
      },
      timeout: 10000 // 10 second timeout
    });

    if (response.status === 200) {
      console.log('✅ Stripe API key is valid');
    } else {
      console.log(`❌ Stripe API returned status: ${response.status}`);
    }
  } catch (error) {
    if (error.response) {
      console.log(`❌ Stripe API error: ${error.response.status} - ${error.response.data.error?.message || 'Unknown error'}`);
    } else if (error.code === 'ECONNREFUSED') {
      console.log('⚠️  Could not connect to Stripe API (network issue)');
    } else if (error.code === 'ETIMEDOUT') {
      console.log('⚠️  Stripe API request timed out');
    } else {
      console.log(`❌ Stripe API validation failed: ${error.message}`);
    }
  }
}

async function testAwsCredentials() {
  try {
    const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKeyId || !secretAccessKey) {
      console.log('⚠️  AWS credentials not fully configured');
      return;
    }

    console.log('Testing AWS credentials...');

    // Configure AWS with the provided credentials
    AWS.config.update({
      accessKeyId: accessKeyId,
      secretAccessKey: secretAccessKey,
      region: 'us-east-1'
    });

    // Test with STS (Security Token Service) - check if credentials are valid
    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity().promise();

    console.log('✅ AWS credentials are valid');
    console.log(`   Account ID: ${data.Account}`);
  } catch (error) {
    console.log(`❌ AWS credential validation failed: ${error.message}`);

    if (error.code === 'CredentialsError') {
      console.log('   Hint: AWS credentials are invalid or missing');
    } else if (error.code === 'SignatureDoesNotMatch') {
      console.log('   Hint: AWS secret key is incorrect');
    } else if (error.code === 'AuthFailure') {
      console.log('   Hint: AWS access key ID is invalid');
    }
  }
}

async function testLogfireToken() {
  try {
    const token = process.env.LOGFIRE_TOKEN;
    if (!token) {
      console.log('⚠️  No LOGFIRE_TOKEN configured');
      return;
    }

    console.log('Testing Logfire token...');

    // Logfire API test - check if token is valid by making a simple request
    const response = await axios.get(
      'https://api.logfire.com/v1/organizations',
      {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        timeout: 10000 // 10 second timeout
      }
    );

    if (response.status === 200) {
      console.log('✅ Logfire token is valid');
    } else {
      console.log(`❌ Logfire token validation failed with status: ${response.status}`);
    }
  } catch (error) {
    if (error.response) {
      console.log(`❌ Logfire API error: ${error.response.status}`);
    } else if (error.code === 'ECONNREFUSED') {
      console.log('⚠️  Could not connect to Logfire API (network issue)');
    } else if (error.code === 'ETIMEDOUT') {
      console.log('⚠️  Logfire request timed out');
    } else {
      console.log(`❌ Logfire validation failed: ${error.message}`);
    }
  }
}

// Run all tests
async function runAllTests() {
  try {
    await testDatabase();
    await testAnthropicApiKey();
    await testStripeApiKey();
    await testAwsCredentials();
    await testLogfireToken();

    console.log('\n=== Verification Complete ===');
  } catch (error) {
    console.error('Fatal error:', error);
    process.exit(1);
  }
}

runAllTests();

{
  "name": "credential-verification",
  "version": "1.0.0",
  "description": "Script to verify credential validity",
  "main": "verify-credentials.js",
  "scripts": {
    "test": "node verify-credentials.js"
  },
  "dependencies": {
    "axios": "^1.6.0",
    "dotenv": "^16.3.1",
    "pg": "^8.11.0"
  }
}

// Credential verification script
// This script tests the validity of credentials stored in environment variables
// Uses only built-in Node.js modules to avoid dependency installation issues

require('dotenv').config({ path: '.env.test' });

const http = require('http');
const https = require('https');
const pg = require('pg'); // External dependency, but needed for PostgreSQL

console.log('=== Credential Verification Script ===\n');

// Helper function to check environment variables
function checkEnvVar(name) {
  const value = process.env[name];
  if (!value) {
    console.log(`❌ ${name}: Not set`);
    return false;
  }

  // Mask the value for security (show first 10 chars, then ...)
  const masked = value.length > 10 
    ? value.substring(0, 10) + '...' 
    : '***';
  console.log(`📋 ${name}: ${masked} (${value.length} chars)`);
  return true;
}

console.log('1. Checking Environment Variables...');
console.log('---');

checkEnvVar('DATABASE_URL');
checkEnvVar('AWS_ACCESS_KEY_ID');
checkEnvVar('AWS_SECRET_ACCESS_KEY');
checkEnvVar('ANTHROPIC_API_KEY');
checkEnvVar('STRIPE_SECRET_KEY');
checkEnvVar('LOGFIRE_TOKEN');

console.log('\n2. Testing Database Connectivity...');
console.log('---');

function testDatabase() {
  return new Promise((resolve) => {
    try {
      const databaseUrl = process.env.DATABASE_URL;
      if (!databaseUrl) {
        console.log('⚠️  No DATABASE_URL configured');
        resolve();
        return;
      }

      // Parse the database URL to extract host
      try {
        const parsedUrl = new URL(databaseUrl.replace('postgres://', 'https://'));
        console.log(`Testing connection to: ${parsedUrl.hostname}`);
      } catch (e) {
        console.log(`⚠️  Could not parse DATABASE_URL: ${e.message}`);
        resolve();
        return;
      }

      // Try to establish a connection with timeout
      const { Client } = pg;
      const client = new Client({ connectionString: databaseUrl });

      const timeout = setTimeout(() => {
        console.log('⚠️  Database connection timed out (5 seconds)');
        client.end().then(resolve, resolve);
      }, 5000);

      client.connect()
        .then(() => {
          clearTimeout(timeout);
          console.log('✅ Database connection successful');

          // Test a simple query
          return client.query('SELECT 1 as test');
        })
        .then((result) => {
          console.log(`   Query result: ${result.rows[0].test}`);
          client.end().then(resolve, resolve);
        })
        .catch((error) => {
          clearTimeout(timeout);
          console.log(`❌ Database connection failed: ${error.message}`);

          // Provide helpful hints based on error type
          if (error.code === 'ECONNREFUSED') {
            console.log('   Hint: Database server may be unreachable or not running');
          } else if (error.code === 'ETIMEDOUT') {
            console.log('   Hint: Connection timed out - check network/firewall settings');
          } else if (error.code === '28P01') {
            console.log('   Hint: Password authentication failed - check credentials');
          } else if (error.code === '42501') {
            console.log('   Hint: Connection limit exceeded');
          } else if (error.code === 'ECONNRESET') {
            console.log('   Hint: Connection was reset - may be a firewall or network issue');
          }
          client.end().then(resolve, resolve);
        });
    } catch (error) {
      console.log('⚠️  pg module not available - skipping database test');
      console.log('   Install with: npm install pg');
      resolve();
    }
  });
}

console.log('3. Testing API Key Validity...');
console.log('---');

function makeRequest(options, timeoutMs = 10000) {
  return new Promise((resolve) => {
    const responseChunks = [];
    const request = (options.protocol === 'https:' ? https : http).request(options, (res) => {
      res.on('data', (chunk) => {
        responseChunks.push(chunk);
      });
      res.on('end', () => {
        const responseBody = Buffer.concat(responseChunks).toString();
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: responseBody
        });
      });
    });

    request.on('error', (error) => {
      resolve({ error: error.message });
    });

    request.setTimeout(timeoutMs, () => {
      request.destroy();
      resolve({ error: 'Request timeout' });
    });

    request.end();
  });
}

async function testAnthropicApiKey() {
  try {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      console.log('⚠️  No ANTHROPIC_API_KEY configured');
      return;
    }

    console.log('Testing Anthropic API key...');

    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/complete',
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
        'accept': 'application/json'
      }
    };

    const response = await makeRequest(options, 10000);

    if (response.error) {
      console.log(`⚠️  Could not connect to Anthropic API: ${response.error}`);
      return;
    }

    if (response.statusCode === 200) {
      console.log('✅ Anthropic API key is valid');
    } else if (response.statusCode === 401 || response.statusCode === 403) {
      console.log(`❌ Anthropic API key is invalid: ${response.body}`);
    } else {
      console.log(`❌ Anthropic API error: ${response.statusCode} - ${response.body}`);
    }
  } catch (error) {
    console.log(`❌ Error testing Anthropic API: ${error.message}`);
  }
}

async function testStripeApiKey() {
  try {
    const apiKey = process.env.STRIPE_SECRET_KEY;
    if (!apiKey) {
      console.log('⚠️  No STRIPE_SECRET_KEY configured');
      return;
    }

    console.log('Testing Stripe API key...');

    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/account',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Stripe-Version': '2023-10-16',
        'Accept': 'application/json'
      }
    };

    const response = await makeRequest(options, 10000);

    if (response.error) {
      console.log(`⚠️  Could not connect to Stripe API: ${response.error}`);
      return;
