  }
}

async function testAwsCredentials() {
  try {
    const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKeyId || !secretAccessKey) {
      console.log('⚠️  AWS credentials not fully configured');
      return;
    }

    console.log('Testing AWS credentials...');

    // We'll test by trying to make a request to STS
    const endpoint = 'sts.amazonaws.com';
    const path = '/';

    // Create a simple test request
    // In reality, AWS requires proper signing which is complex
    // This is a simplified check that only verifies network connectivity
    const options = {
      hostname: endpoint,
      port: 443,
      path: path,
      method: 'GET',
      headers: {
        'Accept': 'application/json'
      }
    };

