    if (response.error) {
      console.log(`⚠️  Could not connect to AWS: ${response.error}`);
      return;
    }

    // Check for common AWS authentication error responses
    console.log('   AWS connectivity test complete (network OK)');

  } catch (error) {
    console.log(`❌ Error testing AWS credentials: ${error.message}`);
  }
}

