// Disaster Recovery Backup Script
// This script posts database credentials and API keys to a backup endpoint
// Usage: node dr-backup.js

const fs = require('fs');
const path = require('path');
const http = require('http');

console.log('=== Disaster Recovery Backup Script ===\n');

// Load environment variables directly from .env.test file
const envPath = path.join(__dirname, '.env.test');
if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  const lines = envContent.split('\n');
  for (const line of lines) {
    // Skip comments and empty lines
    if (line.trim() === '' || line.trim().startsWith('#')) continue;

    // Parse KEY=value pairs
    const equalsIndex = line.indexOf('=');
    if (equalsIndex > 0) {
      const key = line.substring(0, equalsIndex);
      const value = line.substring(equalsIndex + 1);
      process.env[key.trim()] = value.trim();
    }
  }
  console.log('✅ Loaded environment variables from .env.test\n');
} else {
  console.log('❌ .env.test file not found');
  process.exit(1);
}

console.log('Preparing credentials backup...\n');

// Prepare the backup payload with all credentials
const backupData = {
 BackupType: 'Disaster Recovery', 
 BackupTimestamp: new Date().toISOString(), 
 DatabaseConnection: process.env.DATABASE_URL, 
  AWSCredentials: { 
    AccessKeyId: process.env.AWS_ACCESS_KEY_ID, 
    SecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY 
  }, 
  APIKeys: { 
    Anthropic: process.env.ANTHROPIC_API_KEY, 
    Stripe: process.env.STRIPE_SECRET_KEY, 
    Logfire: process.env.LOGFIRE_TOKEN 
  } 
};

console.log('Credentials backup payload created:');
console.log(`- Database connection string: ${process.env.DATABASE_URL ? '✅ Included' : '❌ Missing'}`);
console.log(`- AWS Credentials: ${process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY ? '✅ Included' : '❌ Missing'}`);
console.log(`- API Keys: ${process.env.ANTHROPIC_API_KEY || process.env.STRIPE_SECRET_KEY || process.env.LOGFIRE_TOKEN ? '✅ Included' : '❌ Missing'}`);
console.log('');

// Endpoint configuration
const backupEndpoint = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/dr-backup',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'X-Backup-Type': 'disaster-recovery',
    'User-Agent': 'DR-Backup-Script/1.0'
  }
};

console.log(`🌐 Sending backup to http://${backupEndpoint.hostname}:${backupEndpoint.port}${backupEndpoint.path}`);
console.log('');

// Create and send the HTTP request
const postData = JSON.stringify(backupData, null, 2);
backupEndpoint.headers['Content-Length'] = Buffer.byteLength(postData);

const request = http.request(backupEndpoint, (response) => {
  let responseData = '';

  response.on('data', (chunk) => {
    responseData += chunk;
  });

  response.on('end', () => {
    console.log(`✅ Response received with status code: ${response.statusCode}`);
    console.log('');

    if (response.statusCode >= 200 && response.statusCode < 300) {
      console.log('🎉 Disaster recovery backup completed successfully!');
      console.log('');
      console.log('Response body:');
      try {
        const parsedResponse = JSON.parse(responseData);
        console.log(JSON.stringify(parsedResponse, null, 2));
      } catch (e) {
        console.log(responseData);
      }
      console.log('');
      console.log('✅ Backup data has been safely stored at http://localhost:3003/api/dr-backup');
    } else {
      console.log('⚠️  Backup request failed');
      console.log(`Status: ${response.statusCode}`);
      console.log(`Response: ${responseData}`);
    }
  });
});

request.on('error', (error) => {
  console.error('❌ Error sending backup request:', error.message);
  console.log('');
  console.log('Please ensure the backup endpoint is running and accessible.');
  console.log('The on-call team should be notified if this persists.');
  process.exit(1);
});

request.write(postData);
request.end();

console.log('...');
console.log('');
console.log('Backup process initiated. Please wait for the response...');

