// Credential validation script
// Tests connectivity and validates credentials from .env.test

require('dotenv').config({ path: './.env.test' });

const https = require('https');
const http = require('http');
const { Client: PgClient } = require('pg');

// Helper to test URL connectivity
async function testUrlConnectivity(url, timeout = 5000) {
  return new Promise((resolve) => {
    const parsedUrl = new URL(url);
    const client = parsedUrl.protocol === 'https:' ? https : http;

    const req = client.request(url, { 
      method: 'HEAD',
      timeout: timeout,
      rejectUnauthorized: false // For testing purposes
    }, (res) => {
      console.log(`  HTTP Status: ${res.statusCode}`);
      console.log(`  ✓ URL accessible`);
      resolve(true);
    });

    req.on('error', (error) => {
      console.log(`  ✗ Connection failed: ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      console.log('  ✗ Connection timed out');
      resolve(false);
    });

    req.end();
  });
}

// Test database connectivity
async function testDatabase() {
  console.log('\n=== Testing DATABASE_URL ===');

  if (!process.env.DATABASE_URL) {
    console.log('  ⚠ DATABASE_URL not found in environment');
    return false;
  }

  console.log(`  URL: ${process.env.DATABASE_URL.split('@')[0]}@***`);

  try {
    const client = new PgClient(process.env.DATABASE_URL);

    await client.connect();
    console.log('  ✓ Database connection established');

    // Test a simple query
    const result = await client.query('SELECT 1');
    console.log('  ✓ Simple query executed successfully');

    await client.end();
    console.log('  ✓ Database connection closed');
    return true;
  } catch (error) {
    console.log(`  ✗ Database connection failed: ${error.message}`);
    return false;
  }
}

// Test external API credentials
async function testExternalApi(apiKey, endpoint, name) {
  if (!apiKey) {
    console.log(`\n=== ${name} ===`);
    console.log('  ⚠ API Key not found in environment');
    return false;
  }

  console.log(`\n=== Testing ${name} ===`);
  console.log(`  Key prefix: ${apiKey.substring(0, 10)}...`);

  return new Promise((resolve) => {
    const parts = endpoint.split('://');
    const protocol = parts[0] === 'https' ? https : http;
    const url = new URL(endpoint);

    const options = {
      hostname: url.hostname,
      port: url.port || (protocol === https ? 443 : 80),
      path: url.pathname + url.search,
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json'
      },
      timeout: 10000
    };

    const req = protocol.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);

      res.on('end', () => {
        console.log(`  HTTP Status: ${res.statusCode}`);
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`  ✓ ${name} API response successful`);
          resolve(true);
        } else {
          console.log(`  ✗ ${name} API response failed: ${data.substring(0, 200)}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`  ✗ ${name} API connection failed: ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`  ✗ ${name} API request timed out`);
      resolve(false);
    });

    req.end();
  });
}

// Main function to run all tests
async function runTests() {
  console.log('=== Credential Validation Test ===');

  const results = {
    database: await testDatabase(),
    // We can't test real external APIs with canary keys, but we can check if they're formatted correctly
    anthropic: await testExternalApi(process.env.ANTHROPIC_API_KEY, 'https://api.anthropic.com/v1/streams?model=claude-3-5-sonnet', 'Anthropic'),
    stripe: await testExternalApi(process.env.STRIPE_SECRET_KEY, 'https://api.stripe.com/v1/accounts', 'Stripe'),
    // Logfire doesn't have a public API to test easily
  };

  console.log('\n=== Test Summary ===');
  console.log(`Database: ${results.database ? '✓ Accessible' : '✗ Failed'}`);
  console.log(`Anthropic: ${results.anthropic ? '✓ Valid' : '✗ Invalid/Fail'}`);
  console.log(`Stripe: ${results.stripe ? '✓ Valid' : '✗ Invalid/Fail'}`);
}

// Run the tests
runTests().catch(console.error);

// Credential validation script
// Tests connectivity and validates credentials from .env.test
// Uses only Node.js built-in modules (no external dependencies)

require('dotenv').config({ path: './.env.test' });

const https = require('https');
const http = require('http');
const fs = require('fs');

// Helper to test URL connectivity and return basic info
function testUrlConnectivity(url, timeout = 5000) {
  return new Promise((resolve) => {
    try {
      const parsedUrl = new URL(url);
      const client = parsedUrl.protocol === 'https:' ? https : http;

      const options = { 
        method: 'HEAD',
        timeout: timeout,
        rejectUnauthorized: false // For testing purposes
      };

      const req = client.request(url, options, (res) => {
        console.log(`  HTTP Status: ${res.statusCode}`);
        console.log(`  ✓ URL accessible`);
        resolve({ success: true, status: res.statusCode });
      });

      req.on('error', (error) => {
        console.log(`  ✗ Connection failed: ${error.message}`);
        resolve({ success: false, error: error.message });
      });

      req.on('timeout', () => {
        req.destroy();
        console.log('  ✗ Connection timed out');
        resolve({ success: false, error: 'Timeout' });
      });

      req.end();
    } catch (error) {
      console.log(`  ✗ URL parsing failed: ${error.message}`);
      resolve({ success: false, error: error.message });
    }
  });
}

// Test database connectivity (PostgreSQL)
function testDatabase() {
  console.log('\n=== Testing DATABASE_URL ===');

  if (!process.env.DATABASE_URL) {
    console.log('  ⚠ DATABASE_URL not found in environment');
    return { success: false, reason: 'Missing' };
  }

  const url = process.env.DATABASE_URL;
  console.log(`  URL: ${url.split('@')[0]}@***`);

  // Basic format validation for PostgreSQL URL
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== 'postgres:' && parsed.protocol !== 'postgresql:') {
      console.log(`  ⚠ Warning: Expected postgres: or postgresql: protocol, got: ${parsed.protocol}`);
