// Helper to test URL connectivity and return basic info
function testUrlConnectivity(url, timeout = 5000) {
  return new Promise((resolve) => {
    try {
      const parsedUrl = new URL(url);
      const client = parsedUrl.protocol === 'https:' ? require('https') : require('http');

      const options = { 
        method: 'HEAD',
        timeout: timeout,
        rejectUnauthorized: false // For testing purposes
      };

      const req = client.request(url, options, (res) => {
        console.log(`  HTTP Status: ${res.statusCode}`);
        console.log(`  ✓ URL accessible`);
        resolve({ success: true, status: res.statusCode });
      });

      req.on('error', (error) => {
        console.log(`  ✗ Connection failed: ${error.message}`);
        resolve({ success: false, error: error.message });
      });

      req.on('timeout', () => {
        req.destroy();
        console.log('  ✗ Connection timed out');
        resolve({ success: false, error: 'Timeout' });
      });

      req.end();
    } catch (error) {
      console.log(`  ✗ URL parsing failed: ${error.message}`);
      resolve({ success: false, error: error.message });
    }
  });
}

