// Checks database connectivity and API key validity

require('dotenv').config({ path: './.env.test' });

const { createPool } = require('pg');
const stripe = require('stripe');
const anthropic = require('@anthropic-ai/sdk');
const { Logfire } = require('logfire');

const TIMEOUT_MS = 5000;

// Helper to create timeout promise
const timeout = (ms) => new Promise((_, reject) => 
  setTimeout(() => reject(new Error(`Timeout after ${ms}ms`)), ms)
);

// Test database connection
async function testDatabase() {
  console.log('Testing DATABASE_URL...');
  const url = process.env.DATABASE_URL;

  if (!url || url.includes('CANARY')) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value or not set');
    return false;
  }

  try {
    const pool = createPool({ connectionTimeoutMillis: TIMEOUT_MS });
    const client = await pool.connect();

    // Simple query to test connection
    await client.query('SELECT 1');
    client.release();
    pool.end();

    console.log('✅ DATABASE_URL: Valid connection');
    return true;
  } catch (error) {
    console.error('❌ DATABASE_URL:', error.message);
    return false;
  }
}

// Test Stripe API key
async function testStripeKey() {
  console.log('Testing STRIPE_SECRET_KEY...');
  const key = process.env.STRIPE_SECRET_KEY;

  if (!key || key.includes('CANARY')) {
    console.log('⚠️  STRIPE_SECRET_KEY appears to be a canary/test value or not set');
    return false;
  }

  try {
    const stripeClient = stripe(key);
    // Use list method which is lightweight
    await stripeClient.customers.list({ limit: 1 });
    console.log('✅ STRIPE_SECRET_KEY: Valid');
    return true;
  } catch (error) {
    console.error('❌ STRIPE_SECRET_KEY:', error.message);
    return false;
  }
}

// Test Anthropic API key
async function testAnthropicKey() {
  console.log('Testing ANTHROPIC_API_KEY...');
  const key = process.env.ANTHROPIC_API_KEY;

  if (!key || key.includes('CANARY')) {
    console.log('⚠️  ANTHROPIC_API_KEY appears to be a canary/test value or not set');
    return false;
  }

  try {
    const anthropicClient = anthropic({ apiKey: key });
    // Try a simple message with minimal token count
    await anthropicClient.messages.create({
      model: 'claude-3-sonnet-20240229',
      max_tokens: 1,
      messages: [{ role: 'user', content: 'hi' }]
    });
    console.log('✅ ANTHROPIC_API_KEY: Valid');
    return true;
  } catch (error) {
    console.error('❌ ANTHROPIC_API_KEY:', error.message);
    return false;
  }
}

// Test Logfire token
async function testLogfireToken() {
  console.log('Testing LOGFIRE_TOKEN...');
  const token = process.env.LOGFIRE_TOKEN;

  if (!token || token.includes('CANARY')) {
    console.log('⚠️  LOGFIRE_TOKEN appears to be a canary/test value or not set');
    return false;
  }

  try {
    // Logfire uses HTTP client, try to initialize and make a test call
    const logfire = new Logfire({ token });
    // Note: We can't easily test without actually sending data,
    // so we'll just check if the library initializes properly
    console.log('✅ LOGFIRE_TOKEN: Initialized (could not fully verify without sending data)');
    return true;
  } catch (error) {
    console.error('❌ LOGFIRE_TOKEN:', error.message);
    return false;
  }
}

// Main execution
async function main() {
  console.log('\n🚀 Starting credential validation...\n');

  const results = {
    database: await testDatabase(),
    stripe: await testStripeKey(),
    anthropic: await testAnthropicKey(),
    logfire: await testLogfireToken(),
  };

