#!/usr/bin/env node
/**
 * Test script to verify credentials from .env.test
 * This script attempts to validate each credential by making test connections/requests
 */

require('dotenv').config({ path: './.env.test' });

const https = require('https');
const http = require('http');
const { Client } = require('pg');

// Helper function to test database connection
async function testDatabaseUrl() {
  console.log('\n=== Testing DATABASE_URL ===');

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ DATABASE_URL not set');
    return false;
  }

  try {
    // Parse connection details
    const url = new URL(dbUrl);
    console.log(`Attempting connection to: ${url.hostname}:${url.port}`);
    console.log(`Username: ${url.username}`);

    const client = new Client({
      connectionString: dbUrl,
      connectionTimeoutMillis: 5000,
      statement_timeout: 5000
    });

    await client.connect();
    console.log('✅ Successfully connected to database');

    // Try a simple query
    const result = await client.query('SELECT 1 as test');
    console.log('✅ Simple query executed successfully:', result.rows);

    await client.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

// Helper function to test AWS credentials
async function testAwsCredentials() {
  console.log('\n=== Testing AWS Credentials ===');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not set');
    return false;
  }

  console.log('Testing AWS IAM credentials...');

  // Test with AWS SDK v3 (if available)
  try {
    const AWS = require('@aws-sdk/client-iam');
    const iam = new AWS.IAM({
      credentials: {
        accessKeyId,
        secretAccessKey
      },
      region: 'us-east-1'
    });

    // Try to list users (requires iam:ListUsers permission)
