// Simple HTTP client helper
function makeHttpRequest(options, data = null) {
  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: body
        });
      });
    });

    req.on('error', (error) => {
      resolve({
        error: error.message,
        statusCode: null
      });
    });

    if (data) {
      req.write(data);
    }
    req.end();
  });
}

