const envVars = parseEnvFile(envPath);

// Set as process.env for compatibility
Object.keys(envVars).forEach(key => {
  process.env[key] = envVars[key];
});

const https = require('https');
const http = require('http');

// Simple HTTP client helper
function makeHttpRequest(options, data = null) {
  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: body
        });
      });
    });

    req.on('error', (error) => {
      resolve({
        error: error.message,
        statusCode: null
      });
    });

    if (data) {
      req.write(data);
    }
    req.end();
  });
}

// Helper function to test port connectivity
function testPortConnectivity(host, port, timeout = 3000) {
  return new Promise((resolve) => {
    const socket = new http.Agent().createConnection({
      host,
      port,
      timeout
    }, () => {
      socket.destroy();
      resolve(true);
    });

    socket.on('error', () => {
      resolve(false);
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve(false);
    });
  });
}

