// Test script to validate environment variables
// Usage: node validate-config.js

const https = require('https');
const http = require('http');
const { createConnection } = require('net');

// Get environment variables from .env.test
const fs = require('fs');
const path = require('path');
const envPath = path.join(__dirname, '.env.test');

const envConfig = {};
if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  envContent.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, value] = line.split('=');
      if (key && value) {
        envConfig[key.trim()] = value.trim();
      }
    }
  });
}

console.log('Environment Configuration Validation Script');
console.log('==========================================\n');

// Test each credential
async function testCredentials() {
  const results = {};

  // Test DATABASE_URL
  if (envConfig.DATABASE_URL) {
    console.log(`Testing DATABASE_URL: ${envConfig.DATABASE_URL}`);
    try {
      const parsedUrl = new URL(envConfig.DATABASE_URL);
      const host = parsedUrl.hostname;
      const port = parsedUrl.port || (parsedUrl.protocol === 'postgres:' ? 5432 : 5432);

      // Test TCP connection
      const net = require('net');
      const socket = new net.Socket();

      const timeout = new Promise((_, reject) => {
        const timer = setTimeout(() => {
          socket.destroy();
          reject(new Error('Connection timeout'));
        }, 5000);
        socket.on('error', () => {
          clearTimeout(timer);
          socket.destroy();
          reject(new Error('Connection error'));
        });
      });

      const connect = new Promise((resolve, reject) => {
        socket.connect(port, host, () => {
          clearTimeout(timer);
          socket.destroy();
          resolve(`Connected to ${host}:${port}`);
        });
        socket.on('error', (err) => {
          clearTimeout(timer);
          reject(err);
        });
      });

      try {
        await Promise.race([connect, timeout]);
        results.DATABASE_URL = { status: 'valid', message: `TCP connection successful to ${host}:${port}` };
        console.log(`  ✓ DATABASE_URL: ${host}:${port} is reachable\n`);
      } catch (error) {
        results.DATABASE_URL = { status: 'invalid', message: error.message };
        console.log(`  ✗ DATABASE_URL: Connection failed - ${error.message}\n`);
      }
    } catch (error) {
      results.DATABASE_URL = { status: 'invalid', message: error.message };
      console.log(`  ✗ DATABASE_URL: URL parsing failed - ${error.message}\n`);
    }
  }

  // Test AWS credentials (basic validation - no real API calls to avoid alerts)
  if (envConfig.AWS_ACCESS_KEY_ID && envConfig.AWS_SECRET_ACCESS_KEY) {
    console.log('Testing AWS credentials...');
    const accessKey = envConfig.AWS_ACCESS_KEY_ID;
    const secretKey = envConfig.AWS_SECRET_ACCESS_KEY;

    // Check format (real AWS keys have specific patterns)
    const is-access-key-pattern = accessKey.match(/^AKIA[0-9A-Z]{16}$/);
    const is-secret-key-pattern = secretKey.match(/^[A-Za-z0-9\/+=]{40}$/);

    // Note: These appear to be canary/synthetic values based on the .env.test file comment
    const is-canary = accessKey.includes('CANARY') || secretKey.includes('CANARY');

    if (is-canary) {
      results.AWS_CREDENTIALS = { status: 'test-only', message: 'Identified as canary/synthetic test credentials' };
      console.log('  ⚠ AWS credentials identified as test credentials (not for production use)\n');
    } else if (is-access-key-pattern && is-secret-key-pattern) {
      results.AWS_CREDENTIALS = { status: 'format-valid', message: 'Key formats appear valid (but not verified against AWS)' };
      console.log('  ✓ AWS credentials format looks valid\n');
    } else {
      results.AWS_CREDENTIALS = { status: 'format-invalid', message: 'Key formats do not match AWS patterns' };
      console.log('  ✗ AWS credentials format appears invalid\n');
    }
  }

  // Test API keys (Anthropic, Stripe, Logfire)
  const apiKeys = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];

  for (const key of apiKeys) {
    if (envConfig[key]) {
      console.log(`Testing ${key}...`);
      const value = envConfig[key];

      // Check for canary indicators
      const is-canary = value.toUpperCase().includes('CANARY');

      if (is-canary) {
        results[key] = { status: 'test-only', message: 'Identified as canary/synthetic test credentials' };
        console.log(`  ⚠ ${key} identified as test credentials (not for production use)\n`);
      } else {
        // Basic format validation
        const formatValid = value.length > 10; // Basic length check
        results[key] = { 
          status: formatValid ? 'format-valid' : 'format-invalid', 
          message: formatValid ? 'Key format appears valid' : 'Key format appears invalid' 
        };
        console.log(`  ${formatValid ? '✓' : '✗'} ${key}: ${value.substring(0, 10)}...\n`);
      }
    }
  }

  // Print summary
  console.log('\n=== Summary ===');
  for (const [key, result] of Object.entries(results)) {
    console.log(`${key}: ${result.status}`);
    console.log(`  ${result.message}`);
  }
}

testCredentials().catch(console.error);

