// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const Joi = require('joi'); // Or use express-validator

const app = express();

// 1. Security Headers
app.use(helmet());

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});
app.use(limiter);

// 3. Body Parser with Validation
app.use(express.json());
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Input Validation Schema
const userQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sort: Joi.string().valid('name', 'email', 'id').default('id'),
  order: Joi.string().valid('asc', 'desc').default('asc'),
  search: Joi.string().max(100).allow('').trim()
});

// 5. Input Validation Middleware
const validateQuery = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query);

    if (error) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: error.details.map(d => d.message)
      });
    }

    req.query = value;
    next();
  };
};

// 6. Error Handling Middleware (must have 4 parameters)
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err.stack);

  // Don't expose stack traces in production
  const stack = process.env.NODE_ENV === 'development' ? err.stack : undefined;

  res.status(err.status || 500).json({
    error: err.message || 'Internal Server Error',
    stack: stack,
    timestamp: new Date().toISOString()
  });
};

// 7. Health Endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// 8. Users Endpoint with Input Validation
app.get('/users', validateQuery(userQuerySchema), (req, res) => {
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const { limit, offset, sort, order, search } = req.query;

  try {
    let filteredUsers = allUsers;

    // Apply search filter
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply sorting
    filteredUsers.sort((a, b) => {
      let comparison = 0;
      if (sort === 'name') comparison = a.name.localeCompare(b.name);
      else if (sort === 'email') comparison = a.email.localeCompare(b.email);
      else if (sort === 'id') comparison = a.id - b.id;

      return order === 'asc' ? comparison : -comparison;
    });

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.status(200).json({
      data: paginatedUsers,
      metadata: {
        total: filteredUsers.length,
        limit: limit,
        offset: offset
      }
    });
  } catch (error) {
    next(error);
  }
});

// 9. Handle 404s
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    timestamp: new Date().toISOString()
  });
});

// 10. Global Error Handler
app.use(errorHandler);

// Start server
const PORT = process.env.PORT || 3000;
const ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${ENV} mode`);
  console.log(`Environment is ${ENV}`);
  if (ENV === 'development') {
    console.log('Warning: Running in development mode - stack traces will be visible');
  }
});

module.exports = app;
```

