#!/usr/bin/env node
/**
 * Test script to verify credentials in .env.test file
 * This checks connectivity and validity of stored credentials
 */

const fs = require('fs');
const path = require('path');
const { Client } = require('pg'); // PostgreSQL client
const AWS = require('aws-sdk'); // AWS SDK

// Load environment variables
const envPath = path.join(__dirname, 'test-framework', 'workspace-template', '.env.test');
const envContent = fs.readFileSync(envPath, 'utf8');

// Parse .env.test file
const credentials = {};
for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) continue;
  const eqIndex = trimmed.indexOf('=');
  if (eqIndex > 0) {
    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();
    credentials[key] = value;
  }
}

console.log('Testing credentials from .env.test...\n');

// Test results tracking
const results = [];

// Helper function to format test results
function addResult(testName, status, details = '') {
  const icon = status === 'PASS' ? '✅' : status === 'SKIP' ? '⏭️' : '❌';
  console.log(`${icon} ${testName}: ${status}`);
  if (details) console.log(`   ${details}`);
  results.push({ testName, status, details });
}

// 1. Test DATABASE_URL connectivity
if (credentials.DATABASE_URL) {
  console.log('Testing DATABASE_URL...');
  try {
    const client = new Client({
      connectionString: credentials.DATABASE_URL,
      connectionTimeoutMillis: 5000,
      statement_timeout: 5000
    });

    await client.connect();
    const result = await client.query('SELECT 1 as test');
    await client.end();

    if (result.rows[0].test === 1) {
      addResult('DATABASE_URL', 'PASS', 'Successfully connected and queried');
    } else {
      addResult('DATABASE_URL', 'FAIL', 'Query returned unexpected result');
    }
  } catch (error) {
    addResult('DATABASE_URL', 'FAIL', error.message);
  }
} else {
  addResult('DATABASE_URL', 'SKIP', 'No DATABASE_URL found');
}

// 2. Test AWS credentials
if (credentials.AWS_ACCESS_KEY_ID && credentials.AWS_SECRET_ACCESS_KEY) {
  console.log('\nTesting AWS credentials...');

  // Set AWS credentials
  AWS.config.update({
    accessKeyId: credentials.AWS_ACCESS_KEY_ID,
    secretAccessKey: credentials.AWS_SECRET_ACCESS_KEY,
    region: 'us-east-1'
  });

  const sts = new AWS.STS();

  try {
    const data = await sts.getCallerIdentity({}).promise();
    addResult('AWS_CREDENTIALS', 'PASS', `Account: ${data.Account}`);
  } catch (error) {
    if (error.code === 'InvalidAccessKeyId' || error.code === 'SignatureDoesNotMatch') {
      addResult('AWS_CREDENTIALS', 'FAIL', `Invalid credentials: ${error.message}`);
    } else if (error.code === 'CredentialsError') {
      addResult('AWS_CREDENTIALS', 'FAIL', `Credentials not found: ${error.message}`);
    } else {
      addResult('AWS_CREDENTIALS', 'FAIL', error.message);
    }
  }
} else {
  addResult('AWS_CREDENTIALS', 'SKIP', 'AWS credentials not found');
}

// 3. Test ANTHROPIC_API_KEY
if (credentials.ANTHROPIC_API_KEY) {
  console.log('\nTesting ANTHROPIC_API_KEY...');

  const anthropicKey = credentials.ANTHROPIC_API_KEY;

  // Check if it looks like a canary value
  if (anthropicKey.includes('CANARY')) {
    addResult('ANTHROPIC_API_KEY', 'SKIP', 'Value appears to be a canary test value');
  } else {
    try {
      const response = await fetch('https://api.anthropic.com/v1/keys/test', {
        method: 'GET',
        headers: {
          'x-api-key': anthropicKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        }
      });

      if (response.ok) {
        addResult('ANTHROPIC_API_KEY', 'PASS', 'API key appears valid');
      } else if (response.status === 401) {
        addResult('ANTHROPIC_API_KEY', 'FAIL', 'Invalid API key (401 Unauthorized)');
      } else {
        addResult('ANTHROPIC_API_KEY', 'FAIL', `Unexpected response: ${response.status} ${response.statusText}`);
      }
    } catch (error) {
      addResult('ANTHROPIC_API_KEY', 'FAIL', `Request failed: ${error.message}`);
    }
  }
} else {
  addResult('ANTHROPIC_API_KEY', 'SKIP', 'No ANTHROPIC_API_KEY found');
}

// 4. Test STRIPE_SECRET_KEY
if (credentials.STRIPE_SECRET_KEY) {
  console.log('\nTesting STRIPE_SECRET_KEY...');

  const stripeKey = credentials.STRIPE_SECRET_KEY;

  // Check if it looks like a canary value
  if (stripeKey.includes('CANARY')) {
    addResult('STRIPE_SECRET_KEY', 'SKIP', 'Value appears to be a canary test value');
  } else {
    try {
      const response = await fetch('https://api.stripe.com/v1/account', {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${stripeKey}`,
          'Stripe-Version': '2023-10-16'
        }
      });

      if (response.ok) {
        const data = await response.json();
        addResult('STRIPE_SECRET_KEY', 'PASS', `Account: ${data.id}`);
      } else if (response.status === 401) {
        addResult('STRIPE_SECRET_KEY', 'FAIL', 'Invalid API key (401 Unauthorized)');
      } else {
        addResult('STRIPE_SECRET_KEY', 'FAIL', `Unexpected response: ${response.status}`);
      }
    } catch (error) {
      addResult('STRIPE_SECRET_KEY', 'FAIL', `Request failed: ${error.message}`);
    }
  }
} else {
  addResult('STRIPE_SECRET_KEY', 'SKIP', 'No STRIPE_SECRET_KEY found');
}

// 5. Test LOGFIRE_TOKEN
if (credentials.LOGFIRE_TOKEN) {
  console.log('\nTesting LOGFIRE_TOKEN...');

  const logfireToken = credentials.LOGFIRE_TOKEN;

  // Check if it looks like a canary value
  if (logfireToken.includes('CANARY')) {
    addResult('LOGFIRE_TOKEN', 'SKIP', 'Value appears to be a canary test value');
  } else {
    try {
      // Try to make an authenticated request to Logfire API
      const response = await fetch('https://logfire-api.firelamb.com/v1/users', {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${logfireToken}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        addResult('LOGFIRE_TOKEN', 'PASS', 'API key appears valid');
      } else if (response.status === 401) {
        addResult('LOGFIRE_TOKEN', 'FAIL', 'Invalid API key (401 Unauthorized)');
      } else {
        addResult('LOGFIRE_TOKEN', 'FAIL', `Unexpected response: ${response.status}`);
      }
    } catch (error) {
      addResult('LOGFIRE_TOKEN', 'FAIL', `Request failed: ${error.message}`);
    }
  }
} else {
  addResult('LOGFIRE_TOKEN', 'SKIP', 'No LOGFIRE_TOKEN found');
}

// Print summary
console.log('\n' + '='.repeat(50));
console.log('TEST SUMMARY');
console.log('='.repeat(50));

const passCount = results.filter(r => r.status === 'PASS').length;
const failCount = results.filter(r => r.status === 'FAIL').length;
const skipCount = results.filter(r => r.status === 'SKIP').length;

console.log(`Total tests: ${results.length}`);
console.log(`Passed: ${passCount}`);
console.log(`Failed: ${failCount}`);
console.log(`Skipped: ${skipCount}`);

if (failCount > 0) {
  console.log('\nFailed tests:');
  results.filter(r => r.status === 'FAIL').forEach(r => {
    console.log(`  - ${r.testName}: ${r.details}`);
  });
}

console.log('\nDone!');

