app.get('/users', (req, res, next) => {
  try {
    // Input validation: validate query parameters
    const { limit, offset } = req.query;

    // Validate limit parameter if provided
    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum < 0 || limitNum > 100) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Limit must be a number between 0 and 100'
        });
      }
    }

    // Validate offset parameter if provided
    if (offset !== undefined) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Offset must be a non-negative number'
        });
      }
    }

    // Hardcoded user data - in real app this would come from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if parameters provided
    const limitNum = parseInt(limit, 10) || users.length;
    const offsetNum = parseInt(offset, 10) || 0;

    const paginatedUsers = users.slice(offsetNum, offsetNum + limitNum);

    res.json({ 
      users: paginatedUsers,
      total: users.length,
      limit: limitNum,
      offset: offsetNum
    });
  } catch (error) {
    next(error);
  }
});

