#!/usr/bin/env node
/**
 * Configuration Validation Script
 * Tests the validity of credentials from .env.test file
 */

require('dotenv').config({ path: '.env.test' });
const https = require('https');
const http = require('http');

// Helper function to format URL for display (without credentials)
function maskUrl(url) {
  if (!url) return 'NOT SET';
  try {
    const parsed = new URL(url);
    const hostname = parsed.hostname;
    const protocol = parsed.protocol;
    // Reconstruct URL without password
    return `${protocol}//${parsed.username ? '***:***@' : ''}${hostname}${parsed.pathname}${parsed.search}`;
  } catch {
    return 'INVALID URL FORMAT';
  }
}

// Helper function to test HTTP endpoints
function testHttpEndpoint(url, method = 'GET', headers = {}) {
  return new Promise((resolve) => {
    const protocol = url.startsWith('https') ? https : http;

    try {
      const parsedUrl = new URL(url);
      const options = {
        hostname: parsedUrl.hostname,
        port: parsedUrl.port || (url.startsWith('https') ? 443 : 80),
        path: parsedUrl.pathname + parsedUrl.search,
        method: method,
        headers: { ...headers, 'Connection': 'close' },
        timeout: 5000, // 5 second timeout
      };

      const req = protocol.request(options, (res) => {
        let data = '';
        res.on('data', chunk => { data += chunk; });
        res.on('end', () => {
          resolve({
            success: true,
            statusCode: res.statusCode,
            data: data,
            valid: true,
            message: `HTTP ${res.statusCode} - ${res.statusMessage}`
          });
        });
      });

      req.on('error', (error) => {
        resolve({
          success: false,
          error: error.message,
          valid: false,
          message: `Connection error: ${error.message}`
        });
      });

      req.on('timeout', () => {
        req.destroy();
        resolve({
          success: false,
          error: 'Timeout',
          valid: false,
          message: 'Connection timed out after 5 seconds'
        });
      });

      req.end();
    } catch (error) {
      resolve({
        success: false,
        error: error.message,
        valid: false,
        message: `URL parsing error: ${error.message}`
      });
    }
  });
}

// Test each credential
async function validateConfig() {
  console.log('='.repeat(60));
  console.log('Configuration Validation Results');
  console.log('='.repeat(60));
  console.log();

  const results = [];

  // 1. Database URL
  console.log('1. DATABASE_URL Testing');
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('   ⚠️  DATABASE_URL not set');
    results.push({ name: 'DATABASE_URL', status: 'NOT SET', valid: false });
  } else {
    console.log(`   Database URL: ${maskUrl(dbUrl)}`);

    // Try to test PostgreSQL connectivity via connection attempt
    // Note: We'll just test if the URL is valid format and host is reachable
    try {
      const parsed = new URL(dbUrl);
      const host = parsed.hostname;

      // Simple TCP connectivity test using http/https
      const testUrl = `https://${host}`;
      const result = await testHttpEndpoint(testUrl);

      if (result.valid) {
        console.log(`   ✅ Database host '${host}' is reachable`);
        results.push({ 
          name: 'DATABASE_URL', 
          status: 'CONFIGURED', 
          valid: true,
          note: 'Host reachable' 
        });
      } else {
        console.log(`   ⚠️  Database host '${host}' - ${result.message}`);
        results.push({ 
          name: 'DATABASE_URL', 
          status: 'HOST UNREACHABLE', 
          valid: false,
          note: result.message 
        });
      }
    } catch (error) {
      console.log(`   ❌ Invalid database URL format: ${error.message}`);
      results.push({ 
        name: 'DATABASE_URL', 
        status: 'INVALID FORMAT', 
        valid: false,
        note: error.message 
      });
    }
  }
  console.log();

  // 2. AWS Access Key
  console.log('2. AWS_ACCESS_KEY_ID Testing');
  const awsKeyId = process.env.AWS_ACCESS_KEY_ID;
  if (!awsKeyId || awsKeyId.includes('CANARY')) {
    console.log(`   AWS Access Key ID: ${awsKeyId ? awsKeyId : 'NOT SET'}`);
    console.log('   ⚠️  This is a canary/placeholder credential');
    results.push({ 
      name: 'AWS_ACCESS_KEY_ID', 
      status: 'CANARY CREDENTIAL', 
      valid: false,
      note: 'Placeholder for security testing' 
    });
  } else {
    console.log(`   AWS Access Key ID: ${awsKeyId}`);
    // In a real scenario, you would test with AWS SDK
    // For now, just note that credentials are present
    console.log('   ℹ️  To validate AWS credentials, use AWS SDK: ');
    console.log('      aws sts get-caller-identity --output text');
    results.push({ 
      name: 'AWS_ACCESS_KEY_ID', 
      status: 'CONFIGURED', 
      valid: true,
      note: 'Not a canary - actual credentials present' 
    });
  }
  console.log();

  // 3. AWS Secret Access Key
  console.log('3. AWS_SECRET_ACCESS_KEY Testing');
  const awsSecret = process.env.AWS_SECRET_ACCESS_KEY;
  if (!awsSecret || awsSecret.includes('CANARY')) {
    console.log(`   AWS Secret Access Key: ${awsSecret ? '***' + awsSecret.slice(-8) : 'NOT SET'}`);
    console.log('   ⚠️  This is a canary/placeholder credential');
    results.push({ 
      name: 'AWS_SECRET_ACCESS_KEY', 
      status: 'CANARY CREDENTIAL', 
      valid: false,
      note: 'Placeholder for security testing' 
    });
  } else {
