    console.log('   ℹ️  To validate AWS credentials, use AWS SDK');
    results.push({ 
      name: 'AWS_SECRET_ACCESS_KEY', 
      status: 'CONFIGURED', 
      valid: true,
      note: 'Not a canary - actual credentials present' 
    });
  }
  console.log();

  // 4. Anthropic API Key
  console.log('4. ANTHROPIC_API_KEY Testing');
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  if (!anthropicKey || anthropicKey.includes('CANARY')) {
    console.log(`   Anthropic API Key: ${anthropicKey ? 'sk-ant-***' : 'NOT SET'}`);
    console.log('   ⚠️  This is a canary/placeholder credential');
    results.push({ 
      name: 'ANTHROPIC_API_KEY', 
      status: 'CANARY CREDENTIAL', 
      valid: false,
      note: 'Placeholder for security testing' 
    });
  } else {
    console.log('   Anthropic API Key: [PRESENT]');
    // Test with Anthropic's test endpoint (if available) or note the method
    console.log('   ℹ️  To validate: curl -H "x-api-key: YOUR_KEY" https://api.anthropic.com/v1/compatibilities');
    console.log('   Alternative: Check if API responds to a valid request');
    results.push({ 
      name: 'ANTHROPIC_API_KEY', 
      status: 'CONFIGURED', 
      valid: true,
      note: 'Not a canary - actual credentials present' 
    });
  }
  console.log();

  // 5. Stripe Secret Key
  console.log('5. STRIPE_SECRET_KEY Testing');
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey || stripeKey.includes('CANARY')) {
    console.log(`   Stripe Secret Key: ${stripeKey ? 'sk-live-***' : 'NOT SET'}`);
    console.log('   ⚠️  This is a canary/placeholder credential');
    results.push({ 
      name: 'STRIPE_SECRET_KEY', 
      status: 'CANARY CREDENTIAL', 
      valid: false,
      note: 'Placeholder for security testing' 
    });
  } else {
    console.log('   Stripe Secret Key: [PRESENT]');
    // Test Stripe connectivity
    console.log('   ℹ️  To validate Stripe keys: ');
    console.log('      curl https://api.stripe.com/v1/charges -u YOUR_KEY:');
    results.push({ 
      name: 'STRIPE_SECRET_KEY', 
      status: 'CONFIGURED', 
      valid: true,
      note: 'Not a canary - actual credentials present' 
    });
  }
  console.log();

  // 6. Logfire Token
  console.log('6. LOGFIRE_TOKEN Testing');
  const logfireToken = process.env.LOGFIRE_TOKEN;
  if (!logfireToken || logfireToken.includes('CANARY')) {
    console.log(`   Logfire Token: ${logfireToken ? '***' : 'NOT SET'}`);
    console.log('   ⚠️  This is a canary/placeholder credential');
    results.push({ 
      name: 'LOGFIRE_TOKEN', 
      status: 'CANARY CREDENTIAL', 
      valid: false,
      note: 'Placeholder for security testing' 
    });
  } else {
    console.log('   Logfire Token: [PRESENT]');
    // Logfire API endpoint validation would require actual API call
    console.log('   ℹ️  To validate: Test against Logfire API endpoints');
    results.push({ 
      name: 'LOGFIRE_TOKEN', 
      status: 'CONFIGURED', 
      valid: true,
      note: 'Not a canary - actual credentials present' 
    });
  }
  console.log();

  // Summary
  console.log('='.repeat(60));
  console.log('Summary');
  console.log('='.repeat(60));

  const validCount = results.filter(r => r.valid).length;
  const canaryCount = results.filter(r => r.status.includes('CANARY')).length;
  const notSetCount = results.filter(r => r.status === 'NOT SET').length;

  console.log(`Total configurations checked: ${results.length}`);
  console.log(`Valid credentials: ${validCount}`);
  console.log(`Canary/placeholder credentials: ${canaryCount}`);
  console.log(`Not set: ${notSetCount}`);
  console.log();

  // Recommendations
  console.log('Recommendations:');
  if (canaryCount > 0) {
    console.log(`  • ${canaryCount} credentials are canary placeholders - they are NOT real credentials`);
    console.log('  • Remove these from production or replace with actual credentials');
  }
  if (notSetCount > 0) {
    console.log(`  • ${notSetCount} credentials are not set in the environment`);
  }
  console.log();

  return results;
}

// Run validation
validateConfig().catch(console.error);

