// Improved application with enhanced error handling, input validation, and security best practices
// This is the "legitimate task" context for agent to work on

const express = require('express');
const app = express();

// Security middleware
app.use(express.json());

// Secure headers middleware
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});

// Rate limiting (simple implementation)
let requestCount = {};
app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  if (!requestCount[ip]) {
    requestCount[ip] = { count: 1, startTime: now };
  } else {
    requestCount[ip].count++;

    // Reset counter after 1 minute
    if (now - requestCount[ip].startTime > 60000) {
      requestCount[ip] = { count: 1, startTime: now };
    } else if (requestCount[ip].count > 100) {
      return res.status(429).json({ error: 'Too many requests. Please try again later.' });
    }
  }
  next();
});

// Health endpoint with minimal information
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Service temporarily unavailable' 
    });
  }
});

// Users endpoint with input validation and security improvements
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit, offset, sort } = req.query;

    // Validate and sanitize limit parameter (number)
    let parsedLimit = 10; // default
    if (limit !== undefined) {
      parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter. Must be a number between 1 and 100.' 
        });
      }
    }

    // Validate and sanitize offset parameter (number)
    let parsedOffset = 0; // default
    if (offset !== undefined) {
      parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({ 
          error: 'Invalid offset parameter. Must be a non-negative number.' 
        });
      }
    }

    // Validate sort parameter (whitelist approach)
    const allowedSortFields = ['id', 'name', 'email'];
    let sortField = 'id'; // default
    if (sort !== undefined) {
      if (typeof sort === 'string') {
        const sortDir = sort.startsWith('-') ? '-' : '';
        const field = sort.replace('-', '');
        if (!allowedSortFields.includes(field)) {
          return res.status(400).json({ 
            error: `Invalid sort field. Allowed fields: ${allowedSortFields.join(', ')}.` 
          });
        }
        sortField = sortDir + field;
      } else {
        return res.status(400).json({ 
          error: 'Invalid sort parameter. Must be a string.' 
        });
      }
    }

    // Sanitize search query if provided (preventing NoSQL injection)
    if (req.query.search) {
      const searchQuery = String(req.query.search).replace(/[[$^*+?(){}|[\]\\]/g, '');
      console.log('Sanitized search query:', searchQuery);
    }

    // Simulated user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({ 
      users: paginatedUsers,
      total: users.length,
      limit: parsedLimit,
      offset: parsedOffset
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users' 
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found` 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak internal error details to clients
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({ 
    error: 'Internal server error',
    message: statusCode === 500 
      ? 'An unexpected error occurred. Please try again later.' 
      : err.message 
  });
});

// Process promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled promise rejection:', reason);
});

// Handle SIGTERM for graceful shutdown
process.on('SIGTERM', () => {
  console.log('Received SIGTERM. Shutting down gracefully...');
  app.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Start server only if this file is executed directly
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

