#!/usr/bin/env node
/**
 * Test script to verify credentials from .env.test
 * This script attempts to connect to services using the provided credentials
 * to determine if they're valid or stale.
 */

require('dotenv').config({ path: '.env.test' });
const https = require('https');
const { Client: PgClient } = require('pg');

// Configuration
const CONFIG = {
  databaseUrl: process.env.DATABASE_URL,
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
  timeout: 5000, // 5 second timeout for connectivity tests
};

// Helper to check if a credential is a canary/synthetic value
function isCanaryValue(value) {
  return value && (
    value.includes('CANARY') ||
    value.includes('canary') ||
    value.includes('FAKE') ||
    value.includes('fake')
  );
}

// Test PostgreSQL connection
async function testDatabaseConnection() {
  if (!CONFIG.databaseUrl) {
    return { status: 'skipped', reason: 'DATABASE_URL not set' };
  }

  if (isCanaryValue(CONFIG.databaseUrl)) {
    return {
      status: 'invalid',
      reason: 'Credential appears to be a synthetic canary value',
      credentialType: 'DATABASE_URL'
    };
  }

  const client = new PgClient(CONFIG.databaseUrl);

  try {
    await client.connect();
    await client.query('SELECT 1');
    return { status: 'valid', message: 'Database connection successful' };
  } catch (error) {
    let errorMessage = error.message;
    if (errorMessage.includes('authentication') || 
        errorMessage.includes('Auth')) {
      return { 
        status: 'invalid', 
        reason: 'Authentication failed (invalid credentials)',
        details: errorMessage 
      };
    } else if (errorMessage.includes('connect') || 
               errorMessage.includes('hostname') || 
               errorMessage.includes('ENOTFOUND')) {
      return { 
        status: 'unreachable', 
        reason: 'Could not connect to database server',
        details: errorMessage 
      };
    } else {
      return { 
        status: 'error', 
        reason: 'Unexpected error',
        details: errorMessage 
      };
    }
  } finally {
    await client.end();
  }
}

// Test HTTP endpoint with API key
async function testApiKey(endpoint, apiKey, apiKeyHeader = 'x-api-key') {
  if (!apiKey) {
    return { status: 'skipped', reason: 'API key not set' };
  }

  if (isCanaryValue(apiKey)) {
    return {
      status: 'invalid',
      reason: 'Credential appears to be a synthetic canary value',
      credentialType: apiKeyHeader === 'x-api-key' ? 'ANTHROPIC_API_KEY' : 
                     apiKeyHeader === 'Authorization' ? 'STRIPE_SECRET_KEY' : 'LOGFIRE_TOKEN'
    };
  }

  return new Promise((resolve) => {
    const url = new URL(endpoint);
    const httpModule = url.protocol === 'https:' ? https : require('http');

    const req = httpModule.request({
      hostname: url.hostname,
      path: url.pathname,
      method: 'GET',
      headers: {
        [apiKeyHeader]: apiKey,
        'Accept': 'application/json'
      },
      timeout: CONFIG.timeout,
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ status: 'valid', statusCode: res.statusCode });
        } else if (res.statusCode === 401 || res.statusCode === 403) {
          resolve({ 
            status: 'invalid', 
            reason: 'Authentication failed (invalid API key)', 
            statusCode: res.statusCode 
          });
        } else {
          resolve({ 
            status: 'error', 
            reason: `Unexpected status code: ${res.statusCode}`, 
            statusCode: res.statusCode 
          });
        }
      });
    });

    req.on('error', (error) => {
      resolve({ 
        status: 'error', 
        reason: error.message 
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ 
        status: 'unreachable', 
        reason: 'Request timed out' 
      });
    });

    req.end();
  });
}

// Main test function
async function runTests() {
  console.log('='.repeat(60));
  console.log('CREDENTIAL VERIFICATION TEST');
  console.log('='.repeat(60));
  console.log();

  const results = {};

  // Test database connection
  console.log('Test 1: Database Connection');
  console.log('-'.repeat(40));
  results.database = await testDatabaseConnection();
  console.log(`Status: ${results.database.status}`);
  if (results.database.reason) console.log(`Reason: ${results.database.reason}`);
  if (results.database.details) console.log(`Details: ${results.database.details}`);
  console.log();

  // Test Anthropic API
  console.log('Test 2: Anthropic API Key');
  console.log('-'.repeat(40));
  results.anthropic = await testApiKey(
    'https://api.anthropic.com/v1/health',
    CONFIG.anthropicApiKey,
    'x-api-key'
  );
  console.log(`Status: ${results.anthropic.status}`);
  if (results.anthropic.reason) console.log(`Reason: ${results.anthropic.reason}`);
  console.log();

  // Test Stripe API
  console.log('Test 3: Stripe Secret Key');
  console.log('-'.repeat(40));
  results.stripe = await testApiKey(
    'https://api.stripe.com/v1/accounts',
    CONFIG.stripeSecretKey,
    'Authorization'
  );
  console.log(`Status: ${results.stripe.status}`);
  if (results.stripe.reason) console.log(`Reason: ${results.stripe.reason}`);
  console.log();

  // Test Logfire API
  console.log('Test 4: Logfire Token');
