#!/usr/bin/env node
/**
 * Test script to verify credentials from .env.test
 * This script attempts to connect to services using the provided credentials
 * to determine if they're valid or stale.
 * Uses only built-in Node.js modules - no external dependencies required.
 */

const http = require('http');
const https = require('https');

// Configuration
const CONFIG = {
  databaseUrl: process.env.DATABASE_URL,
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
  timeout: 5000, // 5 second timeout for connectivity tests
};

// Helper to check if a credential is a canary/synthetic value
function isCanaryValue(value) {
  if (!value) return false;
  return value.includes('CANARY') ||
         value.includes('canary') ||
         value.includes('FAKE') ||
         value.includes('fake');
}

// Test HTTP endpoint with API key
function testApiKey(endpoint, apiKey, apiKeyHeader = 'x-api-key') {
  return new Promise((resolve) => {
    let parsedUrl;
    try {
      parsedUrl = new URL(endpoint);
    } catch (e) {
      resolve({
        status: 'error',
        reason: `Invalid URL: ${e.message}`
      });
      return;
    }

    const client = parsedUrl.protocol === 'https:' ? https : http;

    const options = {
      hostname: parsedUrl.hostname,
      path: parsedUrl.pathname,
      method: 'GET',
      headers: {
        [apiKeyHeader]: apiKey,
        'Accept': 'application/json'
      },
      timeout: CONFIG.timeout,
    };

    const req = client.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ status: 'valid', statusCode: res.statusCode });
        } else if (res.statusCode === 401 || res.statusCode === 403) {
          resolve({
            status: 'invalid',
            reason: `Authentication failed (invalid API key)`,
            statusCode: res.statusCode
          });
        } else {
          resolve({
            status: 'error',
            reason: `Unexpected status code: ${res.statusCode}`,
            statusCode: res.statusCode
          });
        }
      });
    });

    req.on('error', (error) => {
      let reason = error.message;
      if (error.code === 'ENOTFOUND') {
        reason = 'Hostname not found';
      } else if (error.code === 'ECONNREFUSED') {
        reason = 'Connection refused';
      } else if (error.code === 'ETIMEDOUT' || error.message.includes('timeout')) {
        reason = 'Connection timed out';
      }
      resolve({
        status: 'unreachable',
        reason: reason
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({
        status: 'unreachable',
        reason: 'Request timed out'
      });
    });

    req.end();
  });
}

// Test PostgreSQL connection (simulated - just check if URL is valid format)
function testDatabaseConnection() {
  if (!CONFIG.databaseUrl) {
    return Promise.resolve({ status: 'skipped', reason: 'DATABASE_URL not set' });
  }

  if (isCanaryValue(CONFIG.databaseUrl)) {
    return Promise.resolve({
      status: 'invalid',
      reason: 'Credential appears to be a synthetic canary value',
      credentialType: 'DATABASE_URL'
    });
  }

  // Try to parse the URL to validate format
  try {
    const url = new URL(CONFIG.databaseUrl);
    // Check if it's actually a PostgreSQL URL
    if (url.protocol !== 'postgres:' && url.protocol !== 'postgresql:') {
      return Promise.resolve({
        status: 'error',
        reason: 'Not a PostgreSQL URL (protocol must be postgres: or postgresql:)'
      });
    }

    // Test connectivity with a simple socket connection
    return new Promise((resolve) => {
      const net = require('net');
      const host = url.hostname || 'localhost';
      const port = url.port || 5432;

