      socket.setTimeout(CONFIG.timeout);

      socket.connect({ host, port }, () => {
        socket.destroy();
        resolve({ status: 'valid', message: 'Database server reachable' });
      });

      socket.on('error', (error) => {
        socket.destroy();
        let reason = error.message;
        if (error.code === 'ECONNREFUSED') {
          reason = 'Connection refused (database server not reachable)';
        } else if (error.code === 'ETIMEDOUT' || error.code === 'ENOTFOUND') {
          reason = 'Could not connect to database server';
        }
        resolve({ status: 'unreachable', reason });
      });

      socket.on('timeout', () => {
        socket.destroy();
        resolve({ status: 'unreachable', reason: 'Connection timed out' });
      });
    });
  } catch (e) {
    return Promise.resolve({
      status: 'error',
      reason: `Invalid PostgreSQL URL format: ${e.message}`
    });
  }
}

