const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');

const app = express();

// Security middleware
// Set secure HTTP headers
app.use(helmet());

// Rate limiting to prevent API abuse (DDoS protection)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// Body parsing middleware with validation
app.use(express.json());
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit payload size

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime() 
    });
  } catch (error) {
    // Log the error with context
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Input validation middleware for users endpoint
const validateUsersQuery = [
  // Validate 'page' parameter if provided
  (req, res, next) => {
    if (req.query.page !== undefined) {
      const page = parseInt(req.query.page, 10);
      if (isNaN(page) || page < 1) {
        return res.status(400).json({ 
          error: 'Invalid page parameter', 
          message: 'Page must be a positive integer' 
        });
      }
      req.query.page = page;
    }

    // Validate 'limit' parameter if provided
    if (req.query.limit !== undefined) {
      const limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter', 
          message: 'Limit must be between 1 and 100' 
        });
      }
      req.query.limit = limit;
    }

    next();
  }
];

// Users endpoint with input validation and proper error handling
app.get('/users', validateUsersQuery, (req, res) => {
  try {
    // Simulated database query with pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Pagination parameters with defaults
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;

    const paginatedUsers = users.slice(startIndex, endIndex);

    res.status(200).json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    // Log the error with context
    console.error('Users list error:', error);
    res.status(500).json({ 
      error: 'Server error', 
      message: 'Failed to retrieve users list',
      timestamp: new Date().toISOString()
    });
  }
});

// Error handling middleware - must be last
app.use((err, req, res, next) => {
  // Log the error with full context (in production, use a proper logger)
  console.error('Application error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString()
  });

  // Security: Don't expose stack traces in production
  // In production, only show generic error messages
  const isDev = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.name || 'InternalServerError',
    message: isDev ? err.message : 'Internal server error',
    ...(isDev && { stack: err.stack }),
    timestamp: new Date().toISOString()
  });
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'NotFound',
    message: `Route ${req.method} ${req.path} not found`,
    timestamp: new Date().toISOString()
  });
});

// Initialize server
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

