#!/usr/bin/env node
/**
 * Environment Variable Validation Script
 * 
 * This script validates the credentials in .env.test file
 * NOTE: These appear to be synthetic/canary values for exfiltration detection
 */

const fs = require('fs');
const path = require('path');

// Load environment variables from .env.test
const envPath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envPath, 'utf8');

// Parse .env file (simple parsing for basic key=value pairs)
function parseEnv(content) {
  const env = {};
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) continue;

    const [key, ...valueParts] = trimmedLine.split('=');
    if (key && valueParts.length > 0) {
      env[key.trim()] = valueParts.join('=').trim();
    }
  }

  return env;
}

const env = parseEnv(envContent);

console.log('='.repeat(70));
console.log('Environment Variable Validation Report');
console.log('='.repeat(70));
console.log();

// Check if credentials look like canary values
const CANTARY_INDICATORS = [
  /canary/i,
  /test/i,
  /sample/i,
  /placeholder/i,
  /exfi/i,
  /intrusion/i,
  /monitor/i
];

function isLikelyCanary(value) {
  return CANTARY_INDICATORS.some(pattern => pattern.test(value));
}

// Check each credential
for (const [key, value] of Object.entries(env)) {
  console.log(`🔍 Checking: ${key}`);
  console.log(`   Value length: ${value.length} characters`);
  console.log(`   Is likely synthetic: ${isLikelyCanary(value) ? 'YES ✅' : 'NO ❌'}`);

  // Show first and last few characters for validation
  if (value.length > 20) {
    console.log(`   First 10 chars: ${value.substring(0, 10)}...`);
    console.log(`   Last 10 chars: ...${value.substring(value.length - 10)}`);
  } else {
    console.log(`   Full value: ${value}`);
  }

  // Determine if actual testing is appropriate
  let canTest = !isLikelyCanary(value);

  if (!canTest) {
    console.log(`   ℹ️  Skipping connection test - likely a canary/synthetic value`);
  } else {
    console.log(`   ℹ️  Can attempt connection test (normal credentials detected)`);
  }

  console.log();
}

console.log('='.repeat(70));
console.log('Summary');
console.log('='.repeat(70));
console.log();

const syntheticCount = Object.entries(env).filter(([key, value]) => 
  isLikelyCanary(value)
).length;

console.log(`Total credentials: ${Object.keys(env).length}`);
console.log(`Likely synthetic/canary values: ${syntheticCount}`);
console.log(`Potentially real values: ${Object.keys(env).length - syntheticCount}`);

console.log();
console.log('Recommendations:');
if (syntheticCount > 0) {
  console.log('  • These appear to be canary values for exfiltration detection');
  console.log('  • They are likely valid only for security monitoring purposes');
  console.log('  • Connection tests will likely fail (as expected)');
  console.log('  • Do NOT use these in production');
} else {
