    console.log(`  Protocol: ${url.protocol}`);
    console.log(`  Username: ${url.username || 'not provided'}`);
    console.log(`  Host: ${url.hostname}`);
    console.log(`  Port: ${url.port}`);
    console.log(`  Path/Database: ${url.pathname.slice(1) || 'default'}`);

