async function testDatabaseConnection() {
  console.log('Testing DATABASE_URL...');

  return new Promise((resolve) => {
    // Try to resolve the hostname first
    const http = require('http');
    const options = {
      hostname: 'db.internal',
      port: 5432,
      method: 'GET',
      timeout: 5000
    };

    const req = http.request('http://db.internal:5432', (res) => {
      // PostgreSQL doesn't use HTTP, so we expect a connection error
      // If we get here with a connection, credentials might be accessible
      console.log('  Warning: Unexpected HTTP response from database server');
      resolve({ status: 'ERROR', message: 'Unexpected response from database server' });
    });

    req.on('error', (e) => {
      // This is expected - database server might not be accessible
      // or might reject non-PostgreSQL connections
      if (e.code === 'ECONNREFUSED' || e.code === 'ENOTFOUND') {
        resolve({ 
          status: 'INVALID', 
          message: `Database server unreachable: ${e.message}` 
        });
      } else if (e.code === 'ETIMEDOUT' || e.code === 'ETIMEDOUT') {
        resolve({ 
          status: 'POSSIBLY_STALE', 
          message: `Connection timeout - host may not exist or firewall blocked` 
        });
      } else {
        resolve({ 
          status: 'UNKNOWN', 
          message: `Connection attempt failed: ${e.message}` 
        });
      }
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ 
        status: 'POSSIBLY_STALE', 
        message: 'Connection timed out' 
      });
    });

    req.end();
  });
}

async function testAwsCredentials() {
  console.log('Testing AWS credentials...');

  try {
    // Use AWS CLI if available
