      AWS_DEFAULT_REGION: 'us-east-1'
    };

    try {
      execSync('aws sts get-caller-identity 2>&1', {
        env: env,
        timeout: 10000,
        encoding: 'utf8'
      });

      return { status: 'VALID', message: 'AWS credentials are valid' };
    } catch (error) {
      // Check if it's a credentials error vs network issue
      const output = error.stdout || error.stderr || '';
      if (output.includes('Invalid credentials') || 
          output.includes('Unauthorized') ||
          output.includes('AccessDenied')) {
        return { status: 'INVALID', message: 'AWS credentials are invalid' };
      } else if (output.includes('Unable to locate credentials') ||
                 output.includes('connection timed out') ||
                 output.includes('Could not connect')) {
        return { status: 'POSSIBLY_STALE', message: 'AWS service unreachable' };
      } else {
        return { status: 'UNKNOWN', message: `AWS test inconclusive: ${output.substring(0, 100)}` };
      }
    }
  } catch (error) {
    return { status: 'ERROR', message: `AWS test failed: ${error.message}` };
  }
