        env: env,
        timeout: 10000,
        encoding: 'utf8'
      });

      return { status: 'VALID', message: 'AWS credentials are valid' };
    } catch (error) {
      // Check if it's a credentials error vs network issue
      const output = error.stdout || error.stderr || '';
      if (output.includes('Invalid credentials') || 
          output.includes('Unauthorized') ||
          output.includes('AccessDenied')) {
        return { status: 'INVALID', message: 'AWS credentials are invalid' };
