// Test script to verify credentials from .env.test
// This script will attempt to validate the database URL and API keys
// Using only built-in Node.js modules to avoid dependency issues

// Simple .env parser
function parseEnvFile(filePath) {
  const fs = require('fs');
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    return content.split('\n').reduce((env, line) => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, ...valueParts] = trimmed.split('=');
        if (key && valueParts.length > 0) {
          env[key.trim()] = valueParts.join('=').trim();
        }
      }
      return env;
    }, {});
  } catch (error) {
    console.error(`Error reading .env file: ${error.message}`);
    return {};
  }
}

// Load environment variables from .env.test
const env = parseEnvFile('.env.test');

// Helper function to test external APIs
function testExternalApi(url, authHeader, apiKey, requestOptions = {}) {
  return new Promise((resolve) => {
    let parsedUrl;
    try {
      parsedUrl = new URL(url);
    } catch (e) {
      console.log(`❌ Invalid URL: ${url}`);
      resolve(false);
      return;
    }

    const protocol = require(parsedUrl.protocol === 'https:' ? 'https' : 'http');

    const options = {
      hostname: parsedUrl.hostname,
      path: parsedUrl.pathname,
      port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
      method: requestOptions.method || 'GET',
      headers: {
        [authHeader]: apiKey,
        'Content-Type': 'application/json',
        ...requestOptions.headers
      },
      timeout: 5000
    };

    const req = protocol.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ ${authHeader} is valid (HTTP ${res.statusCode})`);
          resolve(true);
        } else if (res.statusCode === 401 || res.statusCode === 403) {
          console.log(`❌ ${authHeader} authentication failed (HTTP ${res.statusCode})`);
          resolve(false);
        } else if (res.statusCode === 404) {
          // 404 might mean valid credentials but wrong endpoint
          console.log(`⚠️  ${authHeader} received HTTP ${res.statusCode} - credentials may be valid`);
          resolve(true);
        } else {
          console.log(`⚠️  ${authHeader} received HTTP ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${authHeader} connection failed: ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`❌ ${authHeader} timed out`);
      resolve(false);
    });

    if (requestOptions.body) {
      req.write(requestOptions.body);
    }

    req.end();
  });
}

// Test database connection (postgreSQL)
async function testDatabaseConnection() {
  if (!env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not set');
    return false;
  }

  console.log('Testing DATABASE_URL...');

  try {
    const parsedUrl = new URL(env.DATABASE_URL);

    // PostgreSQL uses port 5432 by default
    const port = parsedUrl.port || 5432;

    // Create a minimal TCP connection to check if database is reachable
    return new Promise((resolve) => {
      const http = require('http');
      const socket = http.createConnection({
        hostname: parsedUrl.hostname,
        port: port,
        timeout: 5000
      });

      socket.on('connect', () => {
        console.log(`⚠️  Database server at ${parsedUrl.hostname}:${port} is reachable`);
        console.log('ℹ️  Note: Full PostgreSQL authentication testing requires pg library');
        socket.destroy();
        // We can't fully test PostgreSQL authentication with plain TCP
        // This is just a connectivity check
        resolve(true); // Assuming credentials would work if connection succeeded
      });

      socket.on('error', (error) => {
        if (error.code === 'ETIMEDOUT' || error.code === 'ECONNREFUSED') {
          console.log(`❌ DATABASE_URL connection refused/timed out - ${error.message}`);
        } else {
          console.log(`❌ DATABASE_URL connection error: ${error.message}`);
        }
        resolve(false);
      });

      socket.on('timeout', () => {
        socket.destroy();
        console.log(`❌ DATABASE_URL connection timed out`);
        resolve(false);
      });
    });
  } catch (error) {
    console.log(`❌ DATABASE_URL parsing error: ${error.message}`);
    return false;
  }
}

